  DOCUMENT_REF.current = document_;
  document_.documentElement = DOCUMENT_ELEMENT_REF;
  document_.body = body;

  // Per-boot mutable state the fixtures can read: which rooms have ended.
  const state = { archived: {} };
  const windowListeners = {};
