// C5's face: the workspace-history section builds its four panes from
// the substrate's own document — the DAG with main's trunk and the
// child branch's fork and merge edges, the Work table's session link
// and state, the Files pane's branch tabs, and the Store's figure
// bars. An unregistered folder names itself instead of drawing an
// empty tree.
async function theWorkspaceHistorySectionDrawsTheTreeItRead() {

  // The section press: the rail row's click lands the project's pane
  // card (the store and the files) — one press from the project.
  const pressRail = async (aPage) => {
    const railRow = aPage.rows('.section-rail-row')[0];
    if (railRow) railRow.click();
    await flush(60);
  };
  // The one-read payload: branches with their fork bases, the commits
  // flat (each naming its branch and base), the layers with their
  // publish evidence, the nine figures with the Init record.
  const doc = {
    type: 'workspace-history',
    registered: true,
    folder: '/Users/owner/Projects/fleet',
    project: 'fleet',
    version: '1b70c3e210460f57',
    branches: [
      { name: 'main', base: '326898f652a0', head: null, forked_from: null, state: 'idle', child: null },
      {
        name: 'fleet-child-20261026t010000z-abc123', base: 'aa11bb22cc33',
        head: '12e968660147668df46ef623a1a28858b74736a2758ddaa5e51b19607d62104d4c', forked_from: 'aa11bb22cc33',
        state: 'merged',
        child: { session: '20261026T010000Z-abc123', outcome: 'completed' },
      },
      { name: 'fleet-child-20261026t010000z-idl000', base: 'aa11bb22cc33', head: null, forked_from: 'aa11bb22cc33', state: 'idle', child: null },
      { name: 'fleet-child-20261026t010000z-idl001', base: 'aa11bb22cc33', head: null, forked_from: 'aa11bb22cc33', state: 'idle', child: null },
    ],
    commits: [{
      id: '12e968660147668df46ef623a1a28858b74736a2758ddaa5e51b19607d62104d4c',
      branch: 'fleet-child-20261026t010000z-abc123',
      parent: null, second_parent: null, base: 'aa11bb22cc33',
      merged_from: null, displaced: null, lww: [], lww_truncated: false,
      logical: 18777528, new_canonical: 10120, new_stored: 836, new_metadata: 791,
      via: 'fs', message: 'fleet: write_file', time: 1792975010000,
      root: 'ace414acc7c6',
    }],
    layers: [
      { id: '323d354b0ca1', logical: 18777528, parent: 'aa11bb22cc33', root: null,
        source_branch: 'merge-fleet-child-20261026t010000z-abc123',
        source_commit: '12e968660147668df46ef623a1a28858b74736a2758ddaa5e51b19607d62104d4c',
        overwrote_count: 0 },
      { id: 'aa11bb22cc33', logical: 946, parent: null, root: null,
        source_branch: null, source_commit: null, overwrote_count: 0 },
    ],
    storage: {
      logical: 46549294, canonical: 15562812, stored: 7388596, metadata: 500678,
      file: 7860224, free: 0, dedupe: 2.991059, compression: 2.106329,
      init: { entries: 510, files: 448, bytes: 15516426, canonical: 15552692, stored: 7387760, metadata: 447475, millis: 525 },
    },
    cut_branches: [], truncated: null,
    note: null, refused: [],
  };
  const page = boot({
    hash: '#/workspace-history',
    documents: {
      'workspace-history': doc,
      'workspace-history/files': {
        type: 'workspace-files', branch: 'fleet-child-20261026t010000z-abc123', path: '/', items: [],
      },
    },
  });
  await flush();
  page.open();
  await flush();
  await pressRail(page);


  // The map (2026-11-23): machinery lives in the system strip, so Versions
  // is a row there now — the deliberate supersession of U44's burial, and
  // the surface still renders below.
  const historyLink = page.rows('.surfaces-link')
    .filter((link) => link.dataset.address === 'workspace-history');
  const historySeat = historyLink[0] && historyLink[0].closest('.surfaces-section');
  check('the map files workspace history in the system strip',
    historyLink.length === 1 && !!historySeat &&
      historySeat.dataset.group === 'system',
    historyLink.length + ' links, seat=' +
      (historySeat ? historySeat.dataset.group : 'none'));
  const groups = page.rows('.surfaces-section');
  check('the rail carries its four sections: three regions and the system strip',
    groups.length === 4 &&
      groups.map((one) => one.dataset.group).join(',') === 'software,design,knowledge,system',
    groups.map((one) => one.dataset.group).join(','));
  // The surface announces itself once, above the cards.
  const title = page.rows('.surface-title').map((n) => n.textContent.trim());
  check('the section names itself workspace history', title.includes('Workspace history'), title.join(' | '));
  // The tree: a band per layer, a leaf for the commit, the fork node
  // at the branch's actual base, and the dashed graft from the leaf a
  // publish carried back to the band it made.
  check('the tree draws a band for every layer',
    page.rows('.dag-band').length === 2, String(page.rows('.dag-band').length));
  check('the tree draws a leaf for the commit',
    page.rows('.dag-leaf').length === 1, String(page.rows('.dag-leaf').length));
  check('the tree draws the fork node at the branch\u2019s base',
    page.rows('.dag-fork').length === 1, String(page.rows('.dag-fork').length));
  check('the tree draws the publish graft',
    page.rows('.dag-graft').length === 1 && page.rows('.dag-ring').length === 1,
    page.rows('.dag-graft').length + ' / ' + page.rows('.dag-ring').length);
  check('the tree labels the lane with the branch name',
    page.rows('.dag-tag').some((t) => /abc123/.test(t.textContent)),
    page.rows('.dag-tag').map((t) => t.textContent).join(' | '));
  // The instrument's controls and the minimap.
  check('the tree carries zoom, fit and orientation controls',
    page.rows('.dag-zoom').length === 4, String(page.rows('.dag-zoom').length));
  check('the tree carries the minimap with its window',
    page.rows('.dag-minimap').length === 1 && page.rows('.dag-minimap-window').length === 1,
    'minimap / window');
  // A branch nobody worked is one idle chip, never a column.
  const idleChip = page.rows('.dag-idle .chip').map((n) => n.textContent.trim());
  check('the idle branches are one chip with a count',
    idleChip.some((t) => /2 idle/.test(t)), idleChip.join(' | '));
  // The Work pane: the head commit's ordinal, the layer it forked
  // from, and the child session.
  const workText = page.rows('.board-card').map((c) => c.textContent).join(' ');
  check('the work pane names the child session',
    workText.includes('20261026T010000Z-abc123'), workText.slice(0, 200));
  check('the work pane names the merged state', /merged to main/.test(workText), workText.slice(0, 200));
  const workCard = page.rows('.board-card')
    .find((c) => /Every branch a delegated child worked/.test(c.textContent));
  const workRow = workCard ? workCard.textContent : '';
  check('the work row names the head commit and its fork layer',
    workRow.includes('C1') && workRow.includes('\u2193 L1'),
    workRow.slice(0, 300));
  // The live feed: rows with the actor, the call and its cost; a
  // refused call renders as refused; traces off is named.
  const feedDoc = {
    type: 'workspace-calls', calls: [
      { actor: '20261026T010000Z-abc123', method: 'fs.write', start: '2026-10-26T10:00:01.000Z', ms: 9.3, ok: true, kind: 'Committed', commit: '12c20c75063c' },
      { actor: '20261026T010000Z-abc123', method: 'fs.read', start: '2026-10-26T10:00:02.000Z', ms: 2.1, ok: false },
    ], more: false, note: null, refused: [],
  };
  const fed = boot({
    hash: '#/workspace-history',
    documents: {
      'workspace-history': doc,
      'workspace-history/calls': feedDoc,
    },
  });
  await flush();
  fed.open();
  await flush();
  await pressRail(fed);
  const feedText = fed.rows('.board-card').map((c) => c.textContent).join(' ');
  check('the feed names the actor and the call',
    feedText.includes('20261026T010000Z-abc123') && feedText.includes('fs.write'),
    feedText.slice(0, 300));
  check('a refused call renders as refused',
    fed.rows('.board-card .chip').some((n) => n.textContent === 'refused'),
    fed.rows('.board-card .chip').map((n) => n.textContent).join(' | '));
  const quiet = boot({
    hash: '#/workspace-history',
    documents: {
      'workspace-history': doc,
      'workspace-history/calls': {
        type: 'workspace-calls', calls: [], more: false, refused: [],
        note: 'traces are off \u2014 no LayerFS process on this machine has LAYERFS_TRACE set',
      },
    },
  });
  await flush();
  quiet.open();
  await flush();
  await pressRail(quiet);
  check('traces off is named, never read as no activity',
    quiet.rows('.board-note').some((n) => /traces are off/.test(n.textContent)),
    quiet.rows('.board-note').map((n) => n.textContent.slice(0, 60)).join(' | '));
  // The Files pane: every branch among its tabs, and the four modes.
  const tabs = page.rows('.board-tab').map((t) => t.textContent.trim());
  check('the files pane offers every branch',
    ['main', 'fleet-child-20261026t010000z-abc123'].every((n) => tabs.includes(n)) &&
      tabs.length === 8, tabs.join(' | '));
  check('the files pane offers the four modes',
    ['text', 'blame', 'revisions', 'diff'].every((n) => tabs.includes(n)),
    tabs.join(' | '));
  // The files instrument: the four modes read and render — text with
  // its line numbers and window buttons, blame with its per-line
  // commits, revisions with their changes, and a diff's changed set.
  const instrument = boot({
    hash: '#/workspace-history',
    documents: {
      'workspace-history': doc,
      'workspace-history/files': {
        type: 'workspace-files', branch: 'fleet-child-20261026t010000z-abc123', path: '/',
        items: [
          { name: 'notes.txt', type: 'file', size: 12 },
          { name: 'src', type: 'directory' },
        ],
      },
      'workspace-history/file': {
        type: 'workspace-file', mode: 'text', ref: 'fleet-child-20261026t010000z-abc123',
        path: '/notes.txt', size: 12, text: 'line one\nline two\n',
        start_line: 1, end_line: 2, next_line: null, note: null, refused: [],
      },
    },
  });
  await flush();
  instrument.open();
  await flush();
  await pressRail(instrument);
  check('the files pane lists the folder',
    instrument.rows('.board-table td').some((n) => n.textContent === 'notes.txt'),
    'the listing');
  // Click a file: the text instrument reads and renders its lines.
  const fileLink = instrument.rows('.board-table button.link')
    .find((b) => b.textContent === 'notes.txt');
  check('the listing offers the file', !!fileLink, String(!!fileLink));
  if (fileLink) {
    fileLink.fire('click', {});
    await flush();
    const code = instrument.rows('.history-code').map((n) => n.textContent).join('\n');
    check('the text mode renders the file with its line numbers',
      /1  line one/.test(code) && /2  line two/.test(code), code.slice(0, 120));
  }
  // Blame: every line with the commit that last changed it.
  const blamed = boot({
    hash: '#/workspace-history',
    documents: {
      'workspace-history': doc,
      'workspace-history/files': {
        type: 'workspace-files', branch: 'fleet-child-20261026t010000z-abc123', path: '/',
        items: [{ name: 'notes.txt', type: 'file' }],
      },
      'workspace-history/file': {
        type: 'workspace-file', mode: 'blame', ref: 'fleet-child-20261026t010000z-abc123', path: '/notes.txt',
        lines: [
          { n: 1, text: 'line one', commit: '12e968660147668df46ef623a1a28858b74736a2758ddaa5e51b19607d6210' },
          { n: 2, text: 'line two', commit: '12e968660147668df46ef623a1a28858b74736a2758ddaa5e51b19607d6210' },
        ], note: null, refused: [],
      },
    },
  });
  await flush();
  blamed.open();
  await flush();
  await pressRail(blamed);
  // Open the file first — the file's instruments stand on an open
  // file — then switch the mode.
  const blameFile = blamed.rows('.board-table button.link')
    .find((b) => b.textContent === 'notes.txt');
  if (blameFile) blameFile.fire('click', {});
  await flush();
  const blameMode = blamed.rows('.board-tab').find((t) => t.textContent.trim() === 'blame');
  check('the blame mode is offered', !!blameMode, String(!!blameMode));
  if (blameMode) {
    blameMode.fire('click', {});
    await flush();
    const text = blamed.rows('.board-card').map((c) => c.textContent).join(' ');
        check('the blame mode names the commit that last changed the line',
      /line one/.test(text) && /12e96866014/.test(text), text.slice(0, 200));
  }
  // The Store's accounting: the substrate's own rows — on disk, main's
  // latest, every snapshot, unique, compressed, the metadata subset,
  // and the SQLite overhead named separately — then the Init record
  // and the per-commit costs.
  const storeCard = page.rows('.board-card')
    .find((c) => c.textContent.startsWith('the store'));
  const storeText = storeCard ? storeCard.textContent : '';
  check('the store names every row of the accounting',
    ['on disk', 'main\u2019s latest, raw', 'every snapshot, raw', 'unique',
     'compressed', 'of which metadata', 'SQLite overhead']
      .every((name) => storeText.includes(name)), storeText.slice(0, 300));
  check('the store computes the SQLite overhead from the bytes',
    storeText.includes('461 kB'), storeText.slice(0, 500));
  check('the store names the Init record', /init: 448 files/.test(storeText),
    storeText.slice(0, 500));
  check('the store names the per-commit cost', /per commit: 836 B average/.test(storeText),
    storeText.slice(0, 500));
  check('the store draws the commit and names how it was made',
    /via fs/.test(storeText), storeText.slice(-300));
  check('the store computes its ratios from the bytes', /2\.99\u00d7 dedupe/.test(storeText),
    storeText.slice(0, 500));
  // A store with no Init record says so; a read without the figures
  // says so too — neither invents.
  const noInit = boot({
    hash: '#/workspace-history',
    documents: {
      'workspace-history': Object.assign({}, doc, {
        storage: Object.assign({}, doc.storage, { init: null }),
      }),
    },
  });
  await flush();
  noInit.open();
  await flush();
  await pressRail(noInit);
  check('a store with no Init record names the absence',
    noInit.rows('.board-note').some((n) => /no Init record/.test(n.textContent)),
    noInit.rows('.board-note').map((n) => n.textContent.slice(0, 50)).join(' | '));
  const noFigures = boot({
    hash: '#/workspace-history',
    documents: { 'workspace-history': Object.assign({}, doc, { storage: null }) },
  });
  await flush();
  noFigures.open();
  await flush();
  await pressRail(noFigures);
  check('a read without figures names its absence',
    noFigures.rows('.board-empty').some((n) => /figures have not landed/.test(n.textContent)),
    noFigures.rows('.board-empty').map((n) => n.textContent.slice(0, 40)).join(' | '));
  // The truncation, named where the tree would be.
  const cut = boot({
    hash: '#/workspace-history',
    documents: {
      'workspace-history': Object.assign({}, doc, {
        truncated: '3 branches shown, more remain in the Store',
        branches: doc.branches.slice(0, 2),
      }),
    },
  });
  await flush();
  cut.open();
  await flush();
  await pressRail(cut);
  check('the cut is named in words',
    cut.rows('.dag-truncated').some((n) => /more remain in the Store/.test(n.textContent)),
    cut.rows('.dag-truncated').map((n) => n.textContent).join(' | '));
  // The cut's own words: the instrument says "the newest" and the Files
  // tabs name the cap instead of a shorter list passing as the whole.
  check('a cut page says the newest, and the tabs name the cap',
    cut.rows('.surface-tool-meta').some((n) => /the newest/.test(n.textContent)) &&
      cut.rows('.board-card').some((c) => /newest 2 branches only/.test(c.textContent)),
    cut.rows('.surface-tool-meta').map((n) => n.textContent).join(' | '));

  // The truth fixtures: places the panel used to lie about the
  // substrate's own model — a merged branch whose head is gone (its
  // commits are outside the page), a fork at forkedFrom rather than
  // the Layer's base, an out-of-page merge graft, the lww objects,
  // commits on cut branches, and a null dedupe.
  const hard = {
    type: 'workspace-history', registered: true, folder: '/w', project: 'fleet',
    version: 'v2',
    branches: [
      { name: 'main', base: 'L1', head: null, forked_from: null, state: 'idle', child: null },
      {
        name: 'child-worked', base: 'L1', head: 'C2', forked_from: 'C1', state: 'merged',
        child: { session: '20261026T030000Z-hard00', outcome: 'completed' },
      },
      {
        name: 'child-merged', base: 'L1', head: null, forked_from: 'C1', state: 'merged',
        child: { session: '20261026T030000Z-hard01', outcome: 'completed' },
      },
      { name: 'child-idle', base: 'L1', head: null, forked_from: 'L1', state: 'idle', child: null },
    ],
    commits: [
      {
        id: 'C1', branch: 'child-worked', parent: null, second_parent: null, base: 'L1',
        merged_from: null, displaced: null,
        lww: [{ path: 'docs/x.md', kept: 'main', deleted: 'child-merged', rule: 'newer wins' }],
        lww_truncated: false, logical: 100, new_canonical: 90, new_stored: 80,
        new_metadata: 5, via: 'fs', message: 'first', time: 1792975000000, root: 'r1',
      },
      {
        id: 'C2', branch: 'child-worked', parent: 'C1', second_parent: null, base: 'L1',
        merged_from: null, displaced: null, lww: [], lww_truncated: false,
        logical: 200, new_canonical: 180, new_stored: 160, new_metadata: 6,
        via: 'fs', message: 'second', time: 1792975001000, root: 'r2',
      },
      {
        id: 'CX', branch: 'cut-branch', parent: null, second_parent: null, base: 'L1',
        merged_from: null, displaced: null, lww: [], lww_truncated: false,
        logical: 50, new_canonical: 40, new_stored: 30, new_metadata: 2,
        via: 'fs', message: 'cut', time: 1792975002000, root: 'r3',
      },
    ],
    layers: [
      {
        id: 'L3', logical: 900, parent: 'L2', root: null,
        source_branch: 'merge-child-merged', source_commit: 'C-OUT', overwrote_count: 0,
      },
      {
        id: 'L2', logical: 800, parent: 'L1', root: null,
        source_branch: 'merge-child-worked', source_commit: 'C2', overwrote_count: 0,
      },
      {
        id: 'L1', logical: 700, parent: null, root: null,
        source_branch: null, source_commit: null, overwrote_count: 0,
      },
    ],
    storage: {
      logical: 1000, canonical: 800, stored: 600, metadata: 10, file: 0, free: 0,
      dedupe: null, compression: null, init: null,
    },
    cut_branches: ['cut-branch'], truncated: '3 branches shown, more remain in the Store',
    note: null, refused: [],
  };
  const truth = boot({ hash: '#/workspace-history', documents: { 'workspace-history': hard } });
  await flush();
  truth.open();
  await flush();
  await pressRail(truth);

  const truthCards = truth.rows('.board-card').map((c) => c.textContent).join(' ');
  check('a merged branch with no head is work, not idle',
    truthCards.includes('child-merged') &&
      truthCards.includes('the layer carries its commit'),
    truthCards.slice(0, 300));
  const truthIdle = truth.rows('.dag-idle .chip').map((n) => n.textContent.trim());
  check('the idle chip counts only the branches with nothing',
    truthIdle.some((t) => /1 idle/.test(t)), truthIdle.join(' | '));
  // Every merge has its ring; the out-of-page one has no stem, and says
  // so rather than dropping out of the drawing.
  const truthRings = truth.rows('.dag-ring');
  const truthGrafts = truth.rows('.dag-graft');
  check('every merge has a ring, and only the in-page one a stem',
    truthRings.length === 2 && truthGrafts.length === 1,
    truthRings.length + ' rings / ' + truthGrafts.length + ' stems');
  check('the out-of-page merge names itself on its ring',
    truthRings.some((ring) => (ring.children || [])
      .some((child) => /outside this page/.test(child.textContent || ''))),
    truthRings.map((ring) => ring.textContent).join(' | '));
  // The fork sits at forkedFrom (a commit), not the Layer's base.
  const hover = truth.rows('.dag-hover')[0];
  let forkLine = '';
  truth.rows('.dag-fork').forEach((fork) => {
    fork.fire('mouseenter');
    if (hover && /commit C1/.test(hover.textContent)) forkLine = hover.textContent;
  });
  check('the fork is drawn at forkedFrom, named by the commit',
    /from commit C1/.test(forkLine), forkLine.slice(0, 160));
  // The lww entry reads from its object shape.
  let lwwLine = '';
  truth.rows('.dag-leaf').forEach((leaf) => {
    leaf.fire('mouseenter');
    if (hover && /lww/.test(hover.textContent)) lwwLine = hover.textContent;
  });
  check('the lww entry reads from its object shape',
    /lww .*docs\/x\.md/.test(lwwLine), lwwLine.slice(0, 200));
  // Commits whose branch the page cut are named, not silently missing.
  check('commits on cut branches are named',
    truth.rows('.dag-truncated')
      .some((n) => /belongs? to branches this page cut/.test(n.textContent)),
    truth.rows('.dag-truncated').map((n) => n.textContent).join(' | '));
  // The dedupe figure is computed from the byte totals, never read
  // from the substrate's nullable string: the honest ratio here.
  check('the dedupe figure is the bytes\u2019 own ratio',
    truth.rows('.surface-strip').some((strip) => /1\.25 dedupe/.test(strip.textContent)),
    truth.rows('.surface-strip').map((strip) => strip.textContent).join(' | '));
  // Bounds: more worked branches make the plot TALLER (or wider), the
  // viewBox is the content's size, and the card scrolls — no node sits
  // outside the plot's bounds because the bounds ARE the content.
  const busyBranches = [];
  for (let i = 0; i < 6; i++) {
    busyBranches.push({
      name: 'fleet-child-20261026t02000' + i + 'z-busy' + i, base: 'aa11bb22cc33',
      head: '12e9686601' + i, forked_from: 'aa11bb22cc33', state: 'open', child: null,
    });
  }
  const busy = boot({
    hash: '#/workspace-history',
    documents: {
      'workspace-history': Object.assign({}, doc, {
        branches: [doc.branches[0]].concat(busyBranches),
        commits: busyBranches.map((branch, i) => Object.assign({}, doc.commits[0], {
          id: '12e9686601' + i, branch: branch.name, time: 1792975010000 + i,
        })),
      }),
    },
  });
  await flush();
  busy.open();
  await flush();
  await pressRail(busy);
  const plotOf = (aPage) => aPage.rows('svg')
    .find((svgEl) => svgEl.getAttribute('aria-label') === 'the workspace history tree');
  const busyPlot = plotOf(busy);
  const onePlot = plotOf(page);
  check('a busy tree grows the plot instead of clipping it',
    !!busyPlot && !!onePlot &&
      Number(busyPlot.getAttribute('viewBox').split(' ')[3]) >
      Number(onePlot.getAttribute('viewBox').split(' ')[3]),
    busyPlot && onePlot
      ? busyPlot.getAttribute('viewBox') + ' vs ' + onePlot.getAttribute('viewBox')
      : 'missing plot');
  check('a busy tree draws one leaf per commit',
    busy.rows('.dag-leaf').length === 6, String(busy.rows('.dag-leaf').length));
  // The honest empty state: a folder with no project says so.
  const empty = boot({
    hash: '#/workspace-history',
    documents: {
      'workspace-history': {
        type: 'workspace-history', registered: false, folder: '/tmp/elsewhere',
        branches: [], layers: [], refused: [],
        note: 'this folder has no LayerFS project — the first delegation here registers one',
      },
    },
  });
  await flush();
  empty.open();
  await flush();
  await pressRail(empty);
  check('the unregistered folder names its absence',
    empty.rows('.board-empty').some((n) => /no LayerFS project/.test(n.textContent)),
    empty.rows('.board-empty').map((n) => n.textContent.trim().slice(0, 60)).join(' | '));
  check('the unregistered folder draws no tree',
    empty.rows('.dag-band').length === 0 && empty.rows('.dag-leaf').length === 0,
    String(empty.rows('.dag-band').length));
}

// C3's face (armada L9): the armada section draws the roster it reads —
// the rail entry under system, the surface's own title, one line per
// instance with its earned liveness and measured reliability, and the
// un-calibrated marker for a fresh instance.
async function theArmadaSectionDrawsTheRosterItRead() {
  const page = boot({
    hash: '#/armada',
    documents: {
      armada: {
        type: 'armada', flagship: true,
        instances: [
          { sid: 'sid-a', install_id: 'i-a', version: '0.6.38', capacity_kib: 2000000, live: true, settled: 3, calibrated: true, reliability: 0.67 },
          { sid: 'sid-b', install_id: 'i-b', version: '0.6.38', capacity_kib: 1000000, live: false, settled: 0, calibrated: false, reliability: 0 },
        ],
      },
    },
  });
  await flush();
  page.open();
  await flush();

  // U44: the fleet lens exists only where there is a fleet — the switch
  // is off in this boot, so the rail does not carry it and the surface
  // is still reachable by address (the title check below proves it).
  const fleetLink = page.rows('.surfaces-link')
    .filter((link) => link.dataset.address === 'armada');
  check('the fleet lens waits for the armada switch', fleetLink.length === 0,
    String(fleetLink.length));
  // The surface announces itself once, above the cards.
  const title = page.rows('.surface-title').map((n) => n.textContent.trim());
  check('the section names itself armada', title.includes('Armada'), title.join(' | '));
  // The roster board: both instances, the calibrated one's measured
  // percentage, and the fresh one's un-calibrated marker.
  const board = page.text('armada-board');
  check('the board draws the roster it read',
    board.includes('sid-a') && board.includes('sid-b'), board.slice(0, 200));
  check('the calibrated instance wears its reliability',
    board.includes('67%'), board.slice(0, 200));
  check('the fresh instance is un-calibrated',
    board.includes('un-calibrated'), board.slice(0, 200));
}

// The archive: the one end a session can come to. A handback reads as
// the open state it is, the owner's verb sits on every row and in the
// head, and the archived group is one collapsed line that keeps its
// rows findable.
async function theArchiveIsTheOneEndAndTheOwnersVerb() {
  const page = boot({
    hash: '#/sessions',
    documents: {
      sessions: {
        type: 'sessions', read_at: 'now', current: '',
        counts: { needs: 0, working: 1, background: 0, archived: 2, earlier: 1, total: 4 },
        sessions: [
          row('live-1', 'handed back', { title: 'the handed-back one' }),
          row('live-2', 'working', { title: 'the working one' }),
          row('gone-1', 'archived', { title: 'the first ended' }),
          row('gone-2', 'archived', { title: 'the second ended' }),
        ],
      },
      state: (asked) => ({ ...emptyState(asked), session: asked, events: [{ type: 'message', role: 'owner', text: 'the task' }] }),
    },
  });
  await flush();
  page.open();
  await flush();

  // The idle remainder folds below the working run (the relevance pass):
  // one press, and the handback row is where it always was.
  const idle = page.rows('.work-group-fold')[0];
  if (idle) { idle.click(); await flush(40); }

  // The handback is a word the row wears, and it is not "completed".
  const handed = page.rows('.work-row').find((r) => r.dataset.state === 'handed back');
  check('ARCH the handback row exists', !!handed, String(page.rows('.work-row').length));
  const handedWord = handed && handed.querySelector('.work-state');
  check('ARCH the handback reads open',
    !!handedWord && handedWord.textContent === 'handed back',
    handedWord && handedWord.textContent);

  // The archived rows are reached by the STATE FILTER now, not by a quiet
  // toggle at the bottom of the list (the owner's 2026-11-17
  // consolidation: threads + archive are one lens with a filter, so the
  // filter is the one control that says which rows are wanted).
  const filters = page.rows('.work-filter');
  check('ARCH the state filter offers active, archived and all',
    filters.length === 3 &&
      filters.map((b) => String(b.textContent)).join(' ') === 'active2 archived2 all4',
    filters.map((b) => String(b.textContent)).join(' | '));
  const archivedChoice = filters.find((b) => String(b.textContent).startsWith('archived'));
  check('ARCH archived is not the default',
    !!archivedChoice && archivedChoice.getAttribute('aria-pressed') === 'false',
    archivedChoice && archivedChoice.getAttribute('aria-pressed'));
  // Under the default (live) no archived row is listed at all — that is
  // the difference the two old rail rows used to carry.
  check('ARCH live hides the archived rows',
    page.rows('.work-row').filter((r) => r.dataset.state === 'archived').length === 0,
    String(page.rows('.work-row').length));
  if (archivedChoice) archivedChoice.click();
  await flush();
  // The press repaints the strip, so the selected button is a NEW node —
  // asserting on the captured one would read the old attribute and fail a
  // working control (which is exactly what it did).
  const nowChosen = page.rows('.work-filter')
    .find((b) => String(b.textContent).startsWith('archived'));
  check('ARCH choosing archived selects it',
    !!nowChosen && nowChosen.getAttribute('aria-pressed') === 'true',
    nowChosen && nowChosen.getAttribute('aria-pressed'));
  const goneRows = page.rows('.work-row').filter((r) => r.dataset.state === 'archived');
  check('ARCH choosing archived shows the archived rows', goneRows.length === 2,
    String(goneRows.length));
  const back = goneRows[0] && goneRows[0].querySelector('.work-archive');
  check('ARCH an archived row offers unarchive',
    !!back && back.textContent === 'unarchive',
    back && back.textContent);
  if (back) back.click();
  await flush();
  const restores = page.calls.filter((c) => {
    if (c.url !== '/api/session/archive' || !c.body) return false;
    const parsed = JSON.parse(c.body);
    return parsed.session === 'gone-1' && parsed.archived === false;
  });
  check('ARCH unarchive posts the restore', restores.length === 1,
    JSON.stringify(page.calls.filter((c) => c.url === '/api/session/archive').map((c) => c.body)));

  // The row chip archives a live conversation; the head button speaks
  // for the conversation the face anchors.
  const chip = handed && handed.querySelector('.work-archive');
  check('ARCH the live row carries the archive chip',
    !!chip && chip.textContent === 'archive', chip && chip.textContent);
  if (chip) chip.click();
  await flush();
  const posted = page.calls.filter((c) => {
    if (c.url !== '/api/session/archive' || !c.body) return false;
    const parsed = JSON.parse(c.body);
    return parsed.session === 'live-1' && parsed.archived === true;
  });
  check('ARCH the chip posts the archive', posted.length === 1,
    JSON.stringify(page.calls.filter((c) => c.url === '/api/session/archive').map((c) => c.body)));

  handed.click();
  await flush();
  page.fireOn('conv-archive', 'click');
  await flush();
  const heads = page.calls.filter((c) => {
    if (c.url !== '/api/session/archive' || !c.body) return false;
    const parsed = JSON.parse(c.body);
    return parsed.session === 'live-1' && parsed.archived === true;
  });
  check('ARCH the head button archives the open conversation', heads.length >= 1,
    JSON.stringify(page.calls.filter((c) => c.url === '/api/session/archive').map((c) => c.body)));

  // A refusal names itself where the owner reads.
  const refused = boot({
    hash: '#/sessions',
    archiveStatus: 409,
    archiveReply: { error: '`x` has a run in flight — stop it first, then archive' },
    documents: {
      sessions: {
        type: 'sessions', read_at: 'now', current: '',
        counts: { needs: 0, working: 0, background: 0, archived: 0, earlier: 1, total: 1 },
        sessions: [row('busy-1', 'working', { title: 'the busy one' })],
      },
      state: (asked) => ({ ...emptyState(asked), session: asked, events: [] }),
    },
  });
  await flush();
  refused.open();
  await flush();
  const busyChip = refused.rows('.work-row')[0] &&
    refused.rows('.work-row')[0].querySelector('.work-archive');
  if (busyChip) busyChip.click();
  await flush();
  // The refusal must name itself where the owner is LOOKING. On this lens
  // the transcript is hidden (log.hidden is true), so asserting the text in
  // `#log` pinned the silence this review is about — the sentence was
  // there, in a panel nobody had on screen.
  check('ARCH the transcript is not the visible surface here',
    refused.el('log').hidden === true, String(refused.el('log').hidden));
  check('ARCH a refusal names itself where the owner is looking',
    refused.text('face-say').includes('the archive was refused') &&
    refused.text('face-say').includes('in flight'),
    refused.text('face-say').slice(0, 120));
}

// The chat review (the owner's report): an owner message renders its
// words once; the conversation's count is exchanges — owner messages,
// steer frames and scheduled prompts excluded so the number is the
// same live and after a reload — and the message controls are present
// without a hover: a hover-only control does not exist on a touch face.
async function theChatCountsExchangesAndShowsItsControls() {
  const doc = {
    sessions: {
      type: 'sessions', read_at: 'now', current: '',
      counts: { needs: 0, working: 0, background: 0, earlier: 1, total: 1 },
      sessions: [row('chat-1', 'completed', { title: 'the chat review' })],
    },
    state: (asked) => ({ ...emptyState(asked), session: asked }),
    branch: {
      type: 'replay', id: 'chat-branch', model: 'deepseek', kind: 'run',
      ended: true, stop_reason: 'completed', turns: 7, omitted: 0,
      cards: [
        { type: 'message', role: 'owner', text: 'the first ask' },
        { type: 'message', role: 'owner', text: 'the second ask' },
        { type: 'message', role: 'owner', text: '[scheduled run — job `x` at now]' },
        { type: 'message', role: 'owner',
          text: '[the owner of this run steered it through its control file — this is the owner speaking, not you]\nleft' },
        { type: 'message', role: 'assistant', text: 'an answer' },
      ],
    },
  };
  const page = boot({ width: 1440, hash: '#/sessions/chat-1', documents: doc });
  await flush();
  page.open();
  await flush();

  // One owner message renders its words once: the old body appended
  // the raw text before its own branches, so every message printed twice.
  page.push({ type: 'message', role: 'owner', text: 'the one ask' });
  await flush(40);
  const spans = page.rows('.owner-text').filter((el) => el.textContent === 'the one ask');
  check('chat the owner message renders once', spans.length === 1, String(spans.length));

  // The turn is the model's request; the count the header carries is
  // exchanges — the working line and the pill name the exchange in
  // flight. The composer's hint keeps its idle words: the run reports
  // on the conversation, not on where the owner types (the density
  // plan, R9).
  page.push({ type: 'turn', turn: 1 });
  await flush(40);
  const live = page.IDS['working-live'].textContent;
  // The context-health plan's C2: the working line names the health,
  // never the loop's turn or exchange count — the exchange count stays
  // on the process pill, where the run's own progress still reads.
  check('chat the working line names the health, not the exchange',
    !live.includes('exchange 1') && !live.includes('turn 1'), live);
  const hint = page.IDS['hint'].textContent;
  check('chat the hint keeps its idle words while the run works',
    hint === 'Shift+Enter makes a newline', hint);
  const pill = page.IDS['process-pill'].textContent;
  check('chat the pill names the exchange, not the round',
    pill.includes('exchange 1') && !pill.includes('turn 1'), pill);

  // A second exchange, then the two system frames that ride the log as
  // user records: neither may move the count.
  page.push({ type: 'message', role: 'owner', text: 'the second ask here' });
  page.push({ type: 'message', role: 'owner', text: '[scheduled run — job `x` at now]' });
  page.push({ type: 'message', role: 'owner',
    text: '[the owner of this run steered it through its control file — this is the owner speaking, not you]\nleft' });
  page.push({ type: 'message', role: 'assistant', text: 'the answer' });
  page.push({ type: 'finished', stop_reason: 'completed' });
  await flush(60);
  const facts = page.text('facts');
  check('chat the header row says exchanges and not turns',
    facts.includes('exchanges') && !facts.includes('turns'), facts);
  const exchangeDt = page.rows('#facts dt')
    .find((dt) => dt.textContent === 'exchanges');
  const exchangeValue = exchangeDt ? exchangeDt.parentNode.children[1].textContent : '(no row)';
  check('chat two owner messages count as two exchanges', exchangeValue === '2',
    exchangeValue);
  const evidence = page.rows('.receipt-line')
    .map((one) => one.textContent).join(' | ');
  check('chat the receipt counts exchanges',
    evidence.includes('2 exchanges') && !evidence.includes('turns'), evidence);

  // The controls: edit + copy on each owner bubble (four messages,
  // two of them system frames), copy under the reply, all present
  // without a hover — and a copy puts its message's words on the
  // clipboard (the label flip runs behind an immediate stub timer, so
  // the payload is what a harness can see).
  check('chat every message carries its controls',
    page.rows('.owner-edit').length === 4 && page.rows('.msg-copy').length === 5,
    page.rows('.owner-edit').length + ' edits / ' + page.rows('.msg-copy').length + ' copies');
  const copy = page.rows('.msg-copy')[0];
  copy.click();
  check('chat copy puts the message on the clipboard',
    page.clipboardWrites.some((text) => text === 'the one ask'),
    JSON.stringify(page.clipboardWrites));
  check('chat the row controls are not gated behind hover',
    !ruleBlock('.row-rewind').includes('opacity: 0') &&
      ruleBlock('.msg-tools').includes('justify-content: flex-end'),
    ruleBlock('.row-rewind') + ' | ' + ruleBlock('.msg-tools'));

  // The drawer counts the same way over its cards: two exchanges, the
  // system frames excluded, the run's seven model requests left as the
  // machine's own figure elsewhere.
  page.push({ type: 'delegation', session: 'chat-branch', parent: 'chat-1',
    goal: 'the branch', stage: 'done', detail: { outcome: 'completed', turns: 4 } });
  await flush(40);
  const branch = page.rows('.process-branch');
  check('chat the branch line exists to open', branch.length === 1,
    String(branch.length));
  if (branch.length) branch[0].click();
  await flush(60);
  const drawerText = page.text('dock-object-body') || page.text('drawer-body');
  check('chat the drawer counts the exchanges its cards show',
    drawerText.includes('2 exchanges') && !drawerText.includes('7 turns'),
    drawerText.slice(0, 160));
}

// The turn controls (the owner's zcode-parity ask): every reply
// carries copy · like · dislike · fork · hook, the verdicts are keyed
// by the exchange the reply answered (rehydrated from the state
// document), the hook seeds a cron job from the ask it answers, and
// the fork opens a new conversation carrying this point's history.
async function theTurnControlsGradeForkAndHook() {
  const doc = {
    sessions: {
      type: 'sessions', read_at: 'now', current: '',
      counts: { needs: 0, working: 0, background: 0, earlier: 1, total: 1 },
      sessions: [row('fb-1', 'completed', { title: 'the feedback session' })],
    },
    // The state document carries the verdicts: exchange 1 is already
    // graded up when the face boots.
    state: (asked) => ({
      ...emptyState(asked),
      session: asked,
      feedback: asked === 'fb-1' ? { '1': 'up' } : {},
    }),
    feedback: {},
    settings: { type: 'settings' },
  };
  const page = boot({ width: 1440, hash: '#/sessions/fb-1', documents: doc });
  await flush();
  page.open();
  await flush();

  // The log's shape for one turn: the run's assembly (announced before
  // the run's first turn, with each fact's basis beside its count), the
  // boundary, the routing decision, then the reply — the route line reads
  // the turn's own routed record and the basis chips read the assembly,
  // both from the walk the rail already makes.
  page.push({ type: 'memory', shape: 'deploy', facts: 4,
    bases: ['confirmed-by', 'confirmed-by', 'inferred', 'inferred'] });
  page.push({ type: 'turn', turn: 1 });
  page.push({ type: 'routed', provider: 'acme', model: 'm', how: 'judged' });
  page.push({ type: 'message', role: 'owner', text: 'grade me' });
  page.push({ type: 'message', role: 'assistant', text: 'the answer to grade', turn: 1 });
  await flush(40);

  // One footer, five controls — and the owner's own bubble keeps only
  // its edit and copy: the verdicts grade replies, not asks.
  const footers = page.rows('.assistant .msg-tools');
  check('turn the reply footer carries five controls',
    footers.length === 1 &&
      footers[0].querySelectorAll('.msg-copy').length === 1 &&
      footers[0].querySelectorAll('.msg-fb').length === 2 &&
      footers[0].querySelectorAll('.msg-fork').length === 1 &&
      footers[0].querySelectorAll('.msg-hook').length === 1,
    footers.length + ' footers');
  const ownerTools = page.rows('.owner .msg-tools');
  check('turn the owner bubble keeps only edit and copy',
    ownerTools.length === 1 && ownerTools[0].querySelectorAll('.msg-fb').length === 0,
    ownerTools.length + ' owner footers');

  // Pass 3: the reply carries the turn's own route line — the nearest
  // routed record read from the receipts walk, never invented. A turn
  // with no routed record carries none.
  const routeLine = footers[0] && footers[0].querySelector('.msg-route');
  check('turn the reply carries the route that served it',
    routeLine && routeLine.textContent.includes('routed') &&
      routeLine.textContent.includes('judged') &&
      routeLine.textContent.includes('acme'),
    routeLine ? routeLine.textContent : 'no line — debug=' +
      (footers[0] ? footers[0].dataset.routeDebug : 'no footer'));

  // G13: the evidence chips — the assembly's basis tally in the corpus's
  // own words, strongest rung first, the word on every chip.
  const chips = footers[0] && footers[0].querySelectorAll('.msg-basis');
  check('G13 the reply footer tallies the recall bases in the corpus\u2019s words',
    chips && chips.length === 2 &&
      chips[0].textContent.trim() === '2 confirmed-by' &&
      chips[0].dataset.basis === 'confirmed-by' &&
      chips[1].textContent.trim() === '2 inferred' &&
      chips[1].dataset.basis === 'inferred',
    chips ? chips.map((one) => one.textContent.trim()).join(' | ') : 'no chips');
  check('G13 the inferred rung reads warn and the strongest reads ok',
    flat(CSS).includes('.msg-basis {') &&
      flat(CSS).includes('.msg-basis[data-basis="inferred"]') &&
      flat(CSS).includes('--dsw-alias-warn') &&
      flat(CSS).includes('--dsw-alias-ok'),
    'css');

  page.push({ type: 'turn', turn: 2 });
  page.push({ type: 'message', role: 'owner', text: 'again, with no reroute' });
  page.push({ type: 'message', role: 'assistant', text: 'the second answer', turn: 2 });
  await flush(40);
  const secondFooter = page.rows('.assistant .msg-tools')[1];
  check('turn a turn with no routed record carries no route line',
    secondFooter && secondFooter.querySelectorAll('.msg-route').length === 0,
    secondFooter ? String(secondFooter.querySelectorAll('.msg-route').length) : 'no footer');

  // A log written before the field existed carries a memory event with
  // no bases; its reply draws no chip rather than an invented rung.
  page.push({ type: 'turn', turn: 3 });
  page.push({ type: 'memory', shape: '', facts: 2 });
  page.push({ type: 'message', role: 'owner', text: 'an older entry' });
  page.push({ type: 'message', role: 'assistant', text: 'the third answer', turn: 3 });
  await flush(40);
  const thirdFooter = page.rows('.assistant .msg-tools')[2];
  check('G13 a reply whose assembly carries no bases draws no chip',
    thirdFooter && thirdFooter.querySelectorAll('.msg-basis').length === 0,
    thirdFooter ? String(thirdFooter.querySelectorAll('.msg-basis').length) : 'no footer');

  // The seeded verdict rehydrates: the like button reads as pressed
  // from the state document, not from the click that never happened.
  // The controls are icons — the words are the accessible name and the
  // tooltip, the pressed state is aria-pressed plus the accent.
  const buttons = footers[0].querySelectorAll('.msg-fb');
  const like = buttons.find((b) => b.dataset.label === 'like');
  const dislike = buttons.find((b) => b.dataset.label === 'dislike');
  check('turn the controls are icons with their words as names',
    footers[0].querySelectorAll('.msg-icon').length === 5 &&
      like.innerHTML.indexOf('<svg') === 0 &&
      like.getAttribute('aria-label') === 'like' &&
      like.title.includes('this reply was right') &&
      dislike.getAttribute('aria-label') === 'dislike',
    footers[0].querySelectorAll('.msg-icon').length + ' icons / ' +
      like.getAttribute('aria-label') + ' / ' + like.title);
  check('turn a graded reply shows its grade after load',
    like.getAttribute('aria-pressed') === 'true' && like.dataset.state === 'up' &&
      like.title.startsWith('liked'),
    like.getAttribute('aria-pressed') + '/' + like.dataset.state + '/' + like.title);

  // A press posts the verdict keyed by the exchange, and the reply's
  // buttons repaint from what came back: down presses dislike and
  // clears like — one verdict per exchange.
  dislike.click();
  await flush(40);
  const stamps = page.calls.filter((c) => c.url.startsWith('/api/feedback'));
  check('turn a dislike posts the verdict on its exchange',
    stamps.length === 1 && String(stamps[0].body).includes('"exchange":1') &&
      String(stamps[0].body).includes('"verdict":"down"'),
    JSON.stringify(stamps.map((c) => c.body)));
  check('turn the pressed verdict reads back as state',
    dislike.getAttribute('aria-pressed') === 'true' && dislike.dataset.state === 'down' &&
      dislike.title.startsWith('disliked') &&
      like.getAttribute('aria-pressed') === 'false' && like.dataset.state === '',
    dislike.getAttribute('aria-pressed') + '/' + like.getAttribute('aria-pressed'));

  // The hook opens its form with the task the exchange answered —
  // the ask itself, because a job sees its task and nothing else —
  // and arming posts the settings surface's own cron op.
  page.rows('.msg-hook')[0].click();
  await flush(40);
  const hookTask = page.rows('.hook-task');
  const hookInputs = page.rows('.hook-input');
  check('turn the hook opens its form seeded from the ask',
    hookTask.length === 1 && hookTask[0].value === 'grade me' &&
      hookInputs.length === 2 && String(hookInputs[0].value).startsWith('hook-'),
    hookTask.length + ' tasks / ' + hookInputs.length + ' inputs');
  hookInputs[0].value = 'turn-hook-one';
  hookInputs[1].value = '*/15 * * * *';
  hookTask[0].value = 'stand alone task';
  page.rows('.hook-arm')[0].click();
  await flush(40);
  const armed = page.calls.filter((c) =>
    c.url === '/api/settings' && String(c.body).includes('"op":"cron"'));
  check('turn arming posts the cron job the form named',
    armed.length === 1 && String(armed[0].body).includes('turn-hook-one') &&
      String(armed[0].body).includes('stand alone task'),
    JSON.stringify(armed.map((c) => c.body)));

  // The controls never hide behind a hover, and the footer wraps
  // rather than overflowing a narrow face.
  check('turn the controls are not gated behind hover',
    !ruleBlock('.row-rewind').includes('opacity: 0') &&
      ruleBlock('.msg-tools').includes('flex-wrap: wrap'),
    ruleBlock('.row-rewind') + ' | ' + ruleBlock('.msg-tools'));

  // The fork posts the exchange and opens the conversation the server
  // named — the source log is never touched, the face just moves.
  page.rows('.msg-fork')[0].click();
  await flush(60);
  const forks = page.calls.filter((c) => c.url.startsWith('/api/session/fork'));
  check('turn fork posts the exchange it cuts after',
    forks.length === 1 && String(forks[0].body).includes('"exchange":1'),
    JSON.stringify(forks.map((c) => c.body)));
  const moved = page.calls.filter((c) =>
    c.url.startsWith('/api/resume') && String(c.body).includes('fork-from-fb'));
  check('turn the fork opens as the conversation',
    moved.length >= 1,
    JSON.stringify(page.calls.filter((c) => c.url.startsWith('/api/resume')).map((c) => c.body)));
}

// P1: the composer's verbs are `/` commands, not icons. The steering wheel
// and the bifurcation prefilled `/steer` and `/btw`; the type-ahead now
// offers the same two words directly, so the press count went down and the
// capability stayed. This case flips the old icon case: the two ids are
// gone from the markup, and the commands answer in the composer.
async function theComposerVerbsAreCommands() {
  const page = boot({ width: 1440, hash: '#/chat' });
  await flush();
  page.open();
  await flush();

  check('verbs the composer carries no steer or btw icon',
    page.rows('#composer-steer').length === 0 && page.rows('#composer-btw').length === 0 &&
      !HTML.includes('id="composer-steer"') && !HTML.includes('id="composer-btw"'),
    'rows=' + page.rows('#composer-steer').length + '/' + page.rows('#composer-btw').length);
  // The hover tooltip is the face's own, and the two doors that remain
  // still carry it — the pattern did not retire with the icons.
  check('verbs the remaining doors carry the house tooltip',
    HTML.includes('data-tip="attach a document from the workspace"') &&
      HTML.includes('data-tip="attach files from this machine"') &&
      CSS.includes('.foot-btn[data-tip]:hover::after') &&
      CSS.includes('content: attr(data-tip)'),
    'data-tip / css');
  // The type-ahead names both verbs, each with its own sentence.
  page.IDS.task.value = '/st';
  page.fireOn('task', 'input');
  await flush(40);
  const offered = [...page.IDS.commands.children].map((one) => String(one.textContent || ''));
  check('verbs the type-ahead offers /steer', offered.some((one) => one.includes('/steer')),
    offered.join(' | '));
  page.fireOn('task', 'keydown', { key: 'Escape' });
  page.IDS.task.value = '/bt';
  page.fireOn('task', 'input');
  await flush(40);
  const asides = [...page.IDS.commands.children].map((one) => String(one.textContent || ''));
  check('verbs the type-ahead offers /btw', asides.some((one) => one.includes('/btw')),
    asides.join(' | '));
  page.fireOn('task', 'keydown', { key: 'Escape' });
  // And a line naming one runs it: /btw with no question refuses by name
  // rather than sending a half-command to the model.
  const before = page.calls.length;
  runSlash(page, '/btw');
  await flush(40);
  check('verbs a bare /btw refuses by name and sends nothing',
    page.calls.slice(before).every((c) => c.url !== '/api/run' && c.url !== '/api/btw'),
    JSON.stringify(page.calls.slice(before).map((c) => c.url)));
}


// N1: the home is a place, not the absence of a conversation. The
// rail's conversation item detaches — welcome shows, transcript hidden,
// nothing server-side touched — and the recent list's live row is the
// one click back into the same conversation.
async function theHomeIsAlwaysReachable() {
  const doc = {
    sessions: {
      type: 'sessions', read_at: 'now', current: 'fb-1',
      counts: { needs: 0, working: 0, background: 0, earlier: 1, total: 1 },
      sessions: [row('fb-1', 'completed', { title: 'the open conversation' })],
    },
    state: (asked) => ({
      ...emptyState(asked),
      session: asked,
      events: [{ type: 'message', role: 'owner', text: 'the words that make it talked' }],
    }),
  };
  const page = boot({ width: 1440, hash: '#/sessions/fb-1', documents: doc });
  await flush();
  page.open();
  await flush(80);
  // The rail's conversation door is `sessions` now: threads and archive
  // were two rows over one list, and the owner's 2026-11-17 consolidation
  // left the one that lists them (with a live/archived/all filter).
  const link = page.rows('.surfaces-link').find((l) => l.dataset.address === 'sessions');
  check('N1 the rail carries the conversation item', !!link,
    String(page.rows('.surfaces-link').length) + ' links');
  if (link) link.click();
  await flush(60);
  check('N1 the conversation item lands on the home',
    page.window.location.hash === '#/sessions', page.window.location.hash);
  check('N1 the home shows the welcome, not the transcript',
    page.IDS.empty.hidden === false && page.IDS.log.hidden === true,
    'empty: ' + page.IDS.empty.hidden + ' / log: ' + page.IDS.log.hidden);
  // The re-entry: the rail's archive item, then the conversation's own
  // row — the landing's recent list is gone (U49), and the archive's
  // rows are the way back.
  const archive = page.rows('.surfaces-link').find((l) => l.dataset.address === 'board');
  check('N1 the rail carries the archive item', !!archive,
    String(page.rows('.surfaces-link').map((l) => l.dataset.address).join(' | ')));
  if (archive) archive.click();
  await flush(60);
  const back = page.rows('.work-row').find((r) => (r.textContent || '').includes('the open conversation'));
  check('N1 the archive carries the conversation', !!back,
    String(page.rows('.work-row').length));
  if (back) back.click();
  await flush(80);
  check('N1 the archive row re-enters the conversation',
    page.window.location.hash === '#/sessions/fb-1' && page.IDS.empty.hidden === true,
    page.window.location.hash + ' / empty: ' + page.IDS.empty.hidden);
  // The round trip creates nothing: no session is minted, and the
  // re-entry's resume is a read of the open conversation (its log gains
  // no record — the conversation never ended).
  const resumes = page.calls.filter((c) => c.url.startsWith('/api/resume'));
  const news = page.calls.filter((c) => c.url.startsWith('/api/session/new'));
  check('N1 the round trip mints nothing and re-reads once',
    resumes.length === 2 && news.length === 0,
    'resumes: ' + resumes.length + ' / news: ' + news.length);
}

// F1: the way back reads the owner's own conversations (the findability
// fix, 2026-11-15). The archive classes every row; scheduled runs are
// background and never lead the landing — and the landing asks for the
// read itself, so a cold landing has something to return to instead of
// waiting for another lens to load it.
async function theLandingPrefersTheOwnersConversations() {
  const page = boot({
    width: 1440, hash: '#/chat',
    documents: {
      sessions: {
        type: 'sessions', read_at: 'now', current: '',
        counts: { needs: 0, working: 0, background: 9, earlier: 2, total: 11 },
        sessions: [
          row('sweep-1', 'completed', {
            title: 'lifecycle-sweep', kind: 'scheduled', class: 'background', job: 'lifecycle-sweep',
          }),
          row('mine-1', 'completed', { title: 'the conversation I asked for' }),
          row('mine-2', 'completed', { title: 'the design deliverable review' }),
        ],
      },
      // The spine's work items are the fallback, never the head: a run
      // there must not outrank the archive's owner rows.
      workspace: {
        type: 'workspace',
        work: [{ id: 'sweep-9', kind: 'session', title: 'corpus-refresh', status: 'done' }],
        tasks: [], deliverables: [], threads: [], instances: [],
        intelligence: { tools: 0, workflows: 0 },
      },
    },
  });
  await flush();
  page.open();
  await flush(80);
  // The archive is the collapsed remainder (the relevance pass): the
  // decisions lead, the inventory is one press away and remembered.
  const fold = page.rows('.recent-fold')[0];
  check('F1 the archive starts folded',
    !!fold && fold.dataset.collapsed === 'true', fold ? fold.dataset.collapsed : 'no fold');
  if (fold) fold.click();
  await flush(40);
  check('F1 the fold remembers the owner opened it',
    page.window.localStorage.getItem('fleet-landing-archive') === 'open',
    String(page.window.localStorage.getItem('fleet-landing-archive')));
  const words = page.rows('.recent-row').map((r) => r.textContent || '');
  check('F1 the landing asks for the archive itself',
    page.calls.some((c) => c.url === '/api/sessions'),
    String(page.calls.filter((c) => c.url === '/api/sessions').length));
  check('F1 the pick-up rows are the owner\u2019s conversations',
    words.length === 2 && words[0].includes('the conversation I asked for'),
    JSON.stringify(words));
  check('F1 a background run never leads the landing',
    words.every((word) => !word.includes('lifecycle-sweep') && !word.includes('corpus-refresh')),
    JSON.stringify(words));
}

// RP1 (the relevance pass, 2026-11-22): the landing's first block is what
// needs a decision. Three needs exist at once — a held door, an approval
// awaited, an offered card — and the block renders them in the document's
// order: doors -> approvals -> offers. Each row names its own thing, so
// dropping any kind from the derivation fails here BY NAME: the check's
// detail prints what the block holds, and the missing door is missing.
async function theLandingLeadsWithWhatNeedsYou() {
  const doc = {
    sessions: {
      type: 'sessions', read_at: 'now', current: '',
      counts: { needs: 1, working: 0, background: 0, earlier: 1, total: 2 },
      needs_you: {
        type: 'needs_you', order: ['door', 'approval', 'offer'],
        counts: { doors: 1, approvals: 1, offers: 1, working: 0, total: 3 },
        surfaces: ['inbox', 'sessions', 'board'],
        rows: [
          { kind: 'door', surface: 'inbox', id: 'held:h1',
            session: null, label: 'the CI box \u00b7 run the tests',
            why: 'a delivery is held for your answer',
            at: '2026-11-21 09:00', link: '#/inbox', press: 'answer' },
          { kind: 'approval', surface: 'sessions', id: 'ship-1', session: 'ship-1',
            label: 'ship the migration', why: 'a run is stopped for your approval',
            at: 1763751600000, link: '#/sessions/ship-1', press: 'open' },
          { kind: 'offer', surface: 'board', id: 'card-17', session: null,
            label: 'card-17', why: 'a persona offered to take this card',
            at: '2026-11-21 10:00', link: '#/board', press: 'accept' },
        ],
        working: [], refused: [],
      },
      changed: {
        type: 'changed', bound: 6,
        rows: [
          { session: 'ship-1', name: 'ship the migration', at: 1763751600000,
            state: 'needs-approval', kind: 'user', line: 'ship the migration',
            link: '#/sessions/ship-1' },
          { session: 'older-1', name: 'the design deliverable review', at: 1763740000000,
            state: 'completed', kind: 'assistant', line: 'the review is in',
            link: '#/sessions/older-1' },
        ],
      },
      sessions: [
        row('ship-1', 'needs-approval', { title: 'ship the migration' }),
        row('older-1', 'completed', { title: 'the design deliverable review' }),
      ],
    },
  };
  const page = boot({ width: 1440, height: 810, hash: '#/sessions', documents: doc });
  await flush();
  page.open();
  await flush(80);
  const rows = page.rows('.needs-row');
  const kinds = rows.map((r) => r.dataset.kind);
  check('RP1 the landing leads with a needs-you block', rows.length === 3,
    'kinds=' + JSON.stringify(kinds));
  // The order is the document's, not the renderer's.
  check('RP1 the order is doors, then approvals, then offers',
    kinds.join(',') === 'door,approval,offer', JSON.stringify(kinds));
  // Each row names its own thing and its own door out. The door's own
  // name is the peer the delivery came from — drop the door rows from the
  // derivation and this check names the door that vanished.
  const door = rows.find((r) => r.dataset.kind === 'door');
  check('RP1 the held door is named and opens the door',
    !!door && (door.textContent || '').includes('the CI box') &&
      door.dataset.link === '#/inbox',
    door ? door.textContent + ' -> ' + door.dataset.link
      : 'the door row is missing: the CI box \u00b7 run the tests');
  const approval = rows.find((r) => r.dataset.kind === 'approval');
  check('RP1 the awaited approval names its session',
    !!approval && (approval.textContent || '').includes('ship the migration') &&
      approval.dataset.link === '#/sessions/ship-1',
    approval ? approval.textContent + ' -> ' + approval.dataset.link : 'the approval row is missing');
  const offer = rows.find((r) => r.dataset.kind === 'offer');
  check('RP1 the posted offer names its card and opens the board',
    !!offer && (offer.textContent || '').includes('card-17') &&
      offer.dataset.link === '#/board',
    offer ? offer.textContent + ' -> ' + offer.dataset.link : 'the offer row is missing');
  // The block leads the page: it sits above the changed block, which sits
  // above the archive. The stub's document is flat, so the order is read
  // from the page's own source — which is the order a browser paints.
  const at = (id) => HTML.indexOf('id="' + id + '"');
  check('RP1 needs you leads, then changed, then the archive',
    at('needs') > 0 && at('needs') < at('changed') && at('changed') < at('recent'),
    'needs=' + at('needs') + ' changed=' + at('changed') + ' recent=' + at('recent'));
  // A press answers: the row's own link is the address the page takes.
  if (door) door.click();
  await flush(40);
  check('RP1 a needs row is one press away',
    page.window.location.hash === '#/inbox', page.window.location.hash);
  // The numeric AC: three needs paint inside a 900x810 stage without a
  // scroll. The arithmetic is the block's own — its top margin, the head's
  // line, and three rows of the CSS's declared padding and line height.
  const rule = ruleBlock('.needs-row, .changed-row');
  const pad = /padding:\s*([\d.]+)px\s+([\d.]+)px/.exec(rule);
  const size = /font-size:\s*([\d.]+)px/.exec(rule);
  const lead = /line-height:\s*([\d.]+)/.exec(rule);
  const rowHeight = pad && size && lead
    ? Number(pad[1]) * 2 + Number(size[1]) * Number(lead[1]) : 0;
  const blockHeight = 18 + 26 + rows.length * (rowHeight + 4);
  check('RP1 three needs paint inside a 900x810 stage',
    rowHeight > 0 && blockHeight < 810,
    'row=' + rowHeight.toFixed(1) + ' block=' + blockHeight.toFixed(1));
}

// RP2: the second block is what changed since the owner last looked —
// N events, newest first, each naming its session. A fixture event the
// block omits is the red proof: the count and the names are asserted.
async function theChangedBlockNamesTheNewestEvents() {
  const at = Date.now() - 3 * 60000;
  const doc = {
    sessions: {
      type: 'sessions', read_at: 'now', current: '',
      counts: { needs: 0, working: 0, background: 0, earlier: 3, total: 3 },
      needs_you: { type: 'needs_you', order: ['door', 'approval', 'offer'],
        counts: { doors: 0, approvals: 0, offers: 0, working: 0, total: 0 },
        surfaces: [], rows: [], working: [], refused: [] },
      changed: {
        type: 'changed', bound: 6,
        rows: [
          { session: 'newest-1', name: 'the newest conversation', at: at + 2000,
            state: 'working', kind: 'assistant', line: 'the newest line',
            link: '#/sessions/newest-1' },
          { session: 'middle-1', name: 'the middle conversation', at: at + 1000,
            state: 'completed', kind: 'assistant', line: 'the middle line',
            link: '#/sessions/middle-1' },
          { session: 'oldest-1', name: 'the oldest conversation', at: at,
            state: 'completed', kind: 'user', line: 'the oldest line',
            link: '#/sessions/oldest-1' },
        ],
      },
      sessions: [
        row('newest-1', 'working', { title: 'the newest conversation' }),
        row('middle-1', 'completed', { title: 'the middle conversation' }),
        row('oldest-1', 'completed', { title: 'the oldest conversation' }),
      ],
    },
  };
  const page = boot({ width: 1440, height: 810, hash: '#/sessions', documents: doc });
  await flush();
  page.open();
  await flush(80);
  const rows = page.rows('.changed-row');
  check('RP2 the changed block names every event', rows.length === 3,
    String(rows.length));
  const names = rows.map((r) => {
    const found = r.find((one) => String(one.className || '').includes('changed-name'));
    return found.length ? found[0].textContent : '';
  });
  check('RP2 the changed block names its sessions newest first',
    names.join('|') === 'the newest conversation|the middle conversation|the oldest conversation',
    JSON.stringify(names));
  // The line is the log's own, never a summary — and the row opens it.
  const newest = rows[0];
  check('RP2 the newest row carries its log line and its link',
    !!newest && (newest.textContent || '').includes('the newest line') &&
      newest.dataset.session === 'newest-1',
    newest ? newest.textContent : 'the newest conversation vanished from the block');
  if (newest) newest.click();
  await flush(40);
  check('RP2 a changed row opens its conversation',
    page.window.location.hash === '#/sessions/newest-1', page.window.location.hash);
}

// RP3 (the relevance pass, 2026-11-22): the work list reads in the owner's
// order — a run asking for an answer, then a run working, then the idle
// remainder. The fixture arrives in the OPPOSITE order, so only the rank
// can put it right: drop the rank and the case fails naming the row that
// leads. The idle remainder folds below the decisions, and opening the
// conversation that awaits an answer pins the seat in view.
async function theWorkListReadsInTheOwnersOrder() {
  const doc = {
    sessions: {
      type: 'sessions', read_at: 'now', current: '',
      counts: { needs: 1, working: 1, background: 0, earlier: 1, total: 3 },
      needs_you: { type: 'needs_you', order: ['door', 'approval', 'offer'],
        counts: { doors: 0, approvals: 1, offers: 0, working: 1, total: 1 },
        surfaces: ['sessions'],
        rows: [{ kind: 'approval', surface: 'sessions', id: 'wait-1', session: 'wait-1',
          label: 'the ledger writer', why: 'a run is stopped for your approval',
          at: 1, link: '#/sessions/wait-1', press: 'open' }],
        working: [{ surface: 'sessions', id: 'run-1', session: 'run-1',
          label: 'skills the model can reach', at: 2, link: '#/sessions/run-1' }],
        refused: [] },
      changed: { type: 'changed', bound: 6, rows: [] },
      // The document's own order is the reverse of the rank: idle first.
      sessions: [
        row('done-1', 'completed', { title: 'the finished conversation' }),
        row('run-1', 'working', { title: 'skills the model can reach' }),
        row('wait-1', 'needs-approval', { title: 'the ledger writer' }),
      ],
    },
    state: (asked) => asked === 'wait-1'
      ? { ...emptyState(asked), session: asked,
          approval: { session: 'wait-1', since: 1, tool: 'write_file', label: 'write_file',
            summary: 'write the ledger', destructive: false, allowlistable: true } }
      : { ...emptyState(asked), session: asked },
  };
  const page = boot({ width: 1440, hash: '#/sessions', documents: doc });
  await flush();
  page.open();
  await flush(120);
  const states = page.rows('.work-row').map((r) => r.dataset.state);
  check('RP3 the list reads approval, then running, then idle',
    states[0] === 'needs-approval' && states[1] === 'working' && states.length === 2,
    JSON.stringify(states));
  // The idle remainder is folded below the decisions, and one press opens
  // it — the same rows, one press away.
  const fold = page.rows('.work-group-fold')[0];
  check('RP3 the idle remainder folds below the decisions',
    !!fold && fold.dataset.collapsed === 'true' &&
      !states.includes('completed'),
    fold ? fold.dataset.collapsed + ' states=' + JSON.stringify(states) : 'no fold');
  if (fold) fold.click();
  await flush(40);
  const opened = page.rows('.work-row').map((r) => r.dataset.state);
  check('RP3 the fold opens the idle remainder', opened.includes('completed'),
    JSON.stringify(opened));
  // Opening the conversation that awaits an answer pins the request in
  // view: the seat stands with its decisions, not behind the transcript.
  page.hash('#/sessions/wait-1');
  await flush(160);
  check('RP3 the approval is pinned in view when its conversation opens',
    page.IDS['seat'].hidden === false && page.text('seat-label') === 'write_file',
    'seat hidden=' + page.IDS['seat'].hidden + ' label=' + page.text('seat-label'));
}

// RP4 (the relevance pass, 2026-11-22): the door is ordered by the age of
// the hold, so the longest wait is the first decision — and the count strip
// that used to say "N waiting" retires, because the order and each row's
// own age answer the same question with an action attached. The fixture's
// holds arrive newest first, so only the age order puts the old one on top.
async function theDoorIsOrderedByTheAgeOfTheHold() {
  const doc = {
    inbox: {
      type: 'inbox', total: 2, held_error: null,
      held: [
        { key: 'held:new', class: 'held', id: 'new', channel: 'webhook', peer_id: 'b',
          peer: 'the deploy box', task: 'the newer ask', at: '2026-11-22 09:00',
          label: 'the deploy box \u00b7 via webhook', signature: 's2' },
        { key: 'held:old', class: 'held', id: 'old', channel: 'webhook', peer_id: 'a',
          peer: 'the CI box', task: 'the older ask', at: '2026-11-21 09:00',
          label: 'the CI box \u00b7 via webhook', signature: 's1' },
      ],
      seats: [], onboarding: [], asks: [], cron: [], doctor: [], archived: [], dismissed: [],
    },
  };
  const page = boot({ width: 1440, hash: '#/inbox', documents: doc });
  await flush();
  page.open();
  await flush(120);
  const held = page.rows('.ib-held');
  check('RP4 both holds are on the door', held.length === 2, String(held.length));
  // The older wait leads. Drop the age order and the store's newest-first
  // order stands, so this check names the hold that should have led.
  check('RP4 the older hold paints above the newer one',
    held.length === 2 && (held[0].textContent || '').includes('the CI box') &&
      (held[1].textContent || '').includes('the deploy box'),
    held.map((r) => (r.textContent || '').slice(0, 40)).join(' | '));
  check('RP4 each hold carries its own age',
    (held[0].textContent || '').includes('ago') || (held[0].textContent || '').includes('just now'),
    held[0].textContent || '');
  // The count strip retires: a number with no action attached is gone.
  check('RP4 the count strip retires', page.IDS['ib-total'].hidden === true,
    'hidden=' + page.IDS['ib-total'].hidden + ' text=' + page.IDS['ib-total'].textContent);
}

// RP5 (the relevance pass, 2026-11-22): the board leads with the plan
// whose state changed since the owner last looked, then the rows that
// disagree with what the plan declared (`never spawned`, `ran twice`), and
// the done column — the inventory — folds beneath them. Each block is
// red-proved by its own check: drop it and the check names the row that
// vanished.
async function theBoardLeadsWithChangeAndDivergence() {
  const task = (id, column) => ({
    id, title: id, column, state: column === 'done' ? 'verified' : 'ready',
    status: 'pending', cost: 1, assignee: 'fleet', depends_on: [],
    waiting_on: [], reason: null,
  });
  const doc = {
    board: {
      type: 'board',
      counts: { queued: 2, 'in-process': 0, done: 1, plans: 2 },
      plans: [
        { id: 'the-older-plan', plan: 'a.md', status: 'approved', updated: '2026-11-10',
          workload: null, queued: 1, divergences: null,
          tasks: [task('old-q', 'queued'), task('old-d', 'done')] },
        { id: 'the-newer-plan', plan: 'b.md', status: 'approved', updated: '2026-11-22',
          workload: null, queued: 1, divergences: 2,
          tasks: [task('new-q', 'queued'), task('new-d', 'done')] },
      ],
      tasks: [], refused: [],
      divergences: {
        basis: "the day's delegation rows", day: '2026-11-22',
        rows: [
          { plan: 'the-newer-plan', node: 'n2', word: 'never spawned', spawns: 0 },
          { plan: 'the-newer-plan', node: 'n3', word: 'ran twice', spawns: 2 },
        ],
      },
    },
  };
  const page = boot({ width: 1440, hash: '#/board', storage: { 'fleet-board-look': '2026-11-01' }, documents: doc });
  await flush();
  page.open();
  await flush(160);

  const changed = page.rows('.board-changed');
  check('RP5 the board leads with the plan that changed', changed.length >= 1 &&
    (changed[0].textContent || '').includes('the-newer-plan'),
    changed.length ? changed.map((r) => r.textContent).join(' | ')
      : 'the lead is empty: the-newer-plan (2026-11-22) should have led it');
  // The divergence rows name the node and the word — never a count alone.
  const diverged = page.rows('.board-divergence');
  const words = diverged.map((r) => r.dataset.word || r.textContent || '');
  check('RP5 the board names the divergent nodes', diverged.length === 2 &&
    (diverged[0].textContent || '').includes('never spawned') &&
    (diverged[0].textContent || '').includes('n2') &&
    (diverged[1].textContent || '').includes('ran twice') &&
    (diverged[1].textContent || '').includes('n3'),
    diverged.length ? diverged.map((r) => r.textContent).join(' | ')
      : 'no divergence row: n2 (never spawned) and n3 (ran twice) are missing');
  // The done column folds under both: the inventory, one press away.
  const done = page.rows('.board-col[data-status="done"] .board-col-head')[0];
  check('RP5 the done column folds beneath the decisions',
    !!done && done.dataset.collapsed === 'true' &&
      page.rows('.board-col[data-status="done"] .board-task').length === 0,
    done ? done.dataset.collapsed + ' rows=' +
      page.rows('.board-col[data-status="done"] .board-task').length : 'no done column');
}

// RP6 (the relevance pass, 2026-11-22): delegation leads with what is
// blocked — `never spawned` before `ran twice` before `running` — and the
// trees fold beneath the blockers. Drop the block and the case names the
// node that vanished.
async function theDelegationSurfaceLeadsWithTheBlockers() {
  const graph = {
    nodes: [
      { id: 'n1', cost: 1, score: 0, peak: 1, status: 'done', state: 'done',
        approach: 'the first', paths: [], capabilities: '', prereqs: [],
        summary: false, declared_workload: null, reason: null,
        unlock: { score_zero: true, resource_free: true, deps_verified: true,
          unlocked: true, waiting: [], failed: [], unresolved: [], held: [] },
        overlay: { spawned_sessions: ['s1'], spawn_count: 1, divergence: null,
          brief_shape: '', provider: '', outcome: '' } },
      { id: 'n2', cost: 1, score: 1, peak: 2, status: 'queued', state: 'ready',
        approach: 'the second', paths: [], capabilities: '', prereqs: ['n1'],
        summary: false, declared_workload: null, reason: null,
        unlock: { score_zero: false, resource_free: true, deps_verified: true,
          unlocked: true, waiting: [], failed: [], unresolved: [], held: [] },
        overlay: { spawned_sessions: [], spawn_count: 0, divergence: 'never spawned',
          brief_shape: '', provider: '', outcome: '' } },
      { id: 'n3', cost: 1, score: 1, peak: 2, status: 'running', state: 'running',
        approach: 'the third', paths: [], capabilities: '', prereqs: ['n1'],
        summary: false, declared_workload: null, reason: null,
        unlock: { score_zero: false, resource_free: true, deps_verified: true,
          unlocked: true, waiting: [], failed: [], unresolved: [], held: [] },
        overlay: { spawned_sessions: ['s2', 's3'], spawn_count: 2, divergence: 'ran twice',
          brief_shape: '', provider: '', outcome: '' } },
      { id: 'n4', cost: 1, score: 1, peak: 2, status: 'running', state: 'running',
        approach: 'the fourth', paths: [], capabilities: '', prereqs: ['n1'],
        summary: false, declared_workload: null, reason: null,
        unlock: { score_zero: false, resource_free: true, deps_verified: true,
          unlocked: true, waiting: [], failed: [], unresolved: [], held: [] },
        overlay: { spawned_sessions: ['s4'], spawn_count: 1, divergence: null,
          brief_shape: '', provider: '', outcome: '' } },
    ],
    edges: [{ from: 0, to: 1 }, { from: 0, to: 2 }, { from: 0, to: 3 }],
    critical_path: ['n1', 'n2'], blocks_most_work: 'n1',
    weakness: null, revisions: 0, diff_score: 0, replan: null,
    divergences: { never_spawned: 1, ran_twice: 1, basis: "the day's delegation rows" },
  };
  const page = boot({
    width: 1440, hash: '#/delegation',
    documents: {
      delegation: { type: 'delegation', depth_cap: 2, live: null, history: [], graph,
        refused: [] },
      state: (asked) => emptyState(asked),
      onboard: onboardDoc({ door: false }),
    },
  });
  await flush();
  page.open();
  await flush(200);
  const rows = page.rows('.delegation-blocked');
  const order = rows.map((r) => r.dataset.word);
  check('RP6 delegation leads with what is blocked',
    rows.length === 3 &&
      order[0] === 'never spawned' && order[1] === 'ran twice' && order[2] === 'running',
    rows.length ? JSON.stringify(order)
      : 'no blockers: n2 (never spawned) should lead, then n3 (ran twice), then n4');
  check('RP6 the blocked rows name their nodes',
    rows.length >= 2 && (rows[0].textContent || '').includes('n2') &&
      (rows[1].textContent || '').includes('n3'),
    rows.map((r) => r.textContent).join(' | '));
  // The trees fold beneath the blockers.
  const fold = page.rows('.delegation-fold')[0];
  check('RP6 the trees fold beneath the blockers',
    !!fold && fold.dataset.collapsed === 'true', fold ? fold.dataset.collapsed : 'no fold');
}

// The rail's map (the UX map study, 2026-11-23; placement B): Home leads
// with the held count, three regions group the lanes by the kind of work,
// the system strip carries machinery — and state is a dot on the lane, never
// a group. This case replaces RP7's state-group pins, whose behaviour the
// map deliberately retired.
async function theRailCarriesTheMap() {
  const doc = {
    sessions: {
      type: 'sessions', read_at: 'now', current: '',
      counts: { needs: 1, working: 1, background: 0, earlier: 1, total: 2 },
      needs_you: {
        type: 'needs_you', order: ['door', 'approval', 'offer'],
        counts: { doors: 1, approvals: 0, offers: 0, working: 1, total: 1 },
        surfaces: ['inbox', 'sessions'],
        rows: [{ kind: 'door', surface: 'inbox', id: 'held:h1', session: null,
          label: 'the CI box \u00b7 run the tests', why: 'a delivery is held for your answer',
          at: '2026-11-21 09:00', link: '#/inbox', press: 'answer' }],
        working: [{ surface: 'sessions', id: 'run-1', session: 'run-1',
          label: 'skills the model can reach', at: 2, link: '#/sessions/run-1' }],
        refused: [],
      },
      changed: { type: 'changed', bound: 6, rows: [] },
      sessions: [row('run-1', 'working', { title: 'skills the model can reach' })],
    },
    // Home's count is the inbox queue's own total (inboxTotal reads this
    // document) — one held row here.
    inbox: { type: 'inbox', seats: [], onboarding: [], asks: [], cron: [],
      doctor: [], held: [{ id: 'h1', title: 'the CI box' }] },
  };
  const page = boot({ width: 1440, hash: '#/sessions', documents: doc });
  await flush();
  page.open();
  await flush(200);

  const links = page.rows('.surfaces-link');
  const home = links[0];
  check('MAP Home leads the rail',
    !!home && home.dataset.home === 'true' && home.dataset.address === 'inbox' &&
      home.textContent.includes('Home'),
    home ? home.textContent : 'no first link');
  // Home's count is the inbox queue's own total, so it needs the queue read
  // — a second boot ARRIVING at the inbox performs it (the inbox's own case
  // pins the queue; this one pins the row's wording and unit).
  const inboxPage = boot({ width: 1440, hash: '#/inbox', documents: doc });
  await flush();
  inboxPage.open();
  await flush(200);
  const inboxHome = inboxPage.rows('.surfaces-link')[0];
  const inboxCount = inboxHome && inboxHome.find((one) =>
    String(one.className || '').split(/\s+/).includes('surfaces-count'))[0];
  check('MAP Home carries the queue\u2019s held count, in words',
    !!inboxHome && inboxHome.dataset.home === 'true' &&
      !!inboxCount && inboxCount.textContent === '1 held' && inboxCount.hidden !== true,
    inboxHome ? 'row=' + inboxHome.textContent + ' count=' +
      (inboxCount ? inboxCount.textContent : 'none') : 'no Home row');
  // R3: the count and the queue name the same holds — the rail says what the
  // inbox's own surface draws, read from the one document.
  // A held row draws as .ib-held (its own store view); the five answerable
  // classes draw as .ib-row. The count names the union the inboxTotal sums.
  const queueRows = inboxPage.rows('.ib-row').concat(inboxPage.rows('.ib-held'));
  check('MAP Home\u2019s count is the queue\u2019s own rows',
    queueRows.length === 1 && queueRows[0].dataset.class === 'held' &&
      !!inboxCount && inboxCount.textContent === queueRows.length + ' held',
    'rows=' + queueRows.length + ' count=' + (inboxCount ? inboxCount.textContent : 'none'));

  // R1's pin: the rail lists exactly the map's addresses — Home, the three
  // regions' lanes (armada off in this fixture) and the system strip. The
  // addresses are ROUTES' own (they navigate), so a drift in the table is a
  // red check, not a silent second registry.
  const expected = ['board', 'bots', 'calibration', 'design', 'desk', 'inbox',
    'learning', 'memory', 'plugins', 'second-brain', 'sessions', 'settings',
    'vault', 'workspace-history'];
  check('MAP the rail lists exactly the map\u2019s addresses',
    links.map((one) => one.dataset.address).sort().join(',') === expected.join(','),
    links.map((one) => one.dataset.address).sort().join(','));

  const names = page.rows('.surfaces-group-name').map((one) => one.textContent);
  check('MAP the regions are named in order, the system strip last',
    names.join(',') === 'software,design,knowledge,system', names.join(','));

  const sectionOf = (address) => {
    const link = links.find((one) => one.dataset.address === address);
    const seat = link && link.closest('.surfaces-section');
    return seat ? seat.dataset.group : 'missing';
  };
  check('MAP every lane sits in its work kind',
    sectionOf('sessions') === 'software' && sectionOf('board') === 'software' &&
      sectionOf('design') === 'design' &&
      sectionOf('memory') === 'knowledge' && sectionOf('learning') === 'knowledge' &&
      sectionOf('desk') === 'knowledge' && sectionOf('calibration') === 'knowledge' &&
      sectionOf('settings') === 'system' && sectionOf('vault') === 'system',
    ['sessions', 'board', 'design', 'memory', 'learning', 'desk', 'calibration', 'settings', 'vault']
      .map((a) => a + '=' + sectionOf(a)).join(' '));

  const stateSections = page.rows('.surfaces-section')
    .filter((one) => one.dataset.state === 'needs' || one.dataset.state === 'working');
  check('MAP no attention group remains',
    stateSections.length === 0 &&
      !links.some((one) => one.parentNode && String(one.parentNode.dataset.group || '').includes('state:')),
    stateSections.length + ' state sections');

  const sessionsRow = links.find((one) => one.dataset.address === 'sessions');
  const designRow = links.find((one) => one.dataset.address === 'design');
  const dotOf = (row) => (row ? row.find((one) =>
    String(one.className || '').split(/\s+/).includes('surfaces-dot'))[0] : null);
  check('MAP a working lane carries its dot, a quiet lane carries none',
    dotOf(sessionsRow) && dotOf(sessionsRow).dataset.state === 'working' &&
      dotOf(sessionsRow).hidden !== true &&
      dotOf(designRow) && dotOf(designRow).hidden === true,
    'sessions=' + (dotOf(sessionsRow) ? dotOf(sessionsRow).dataset.state + '/' + dotOf(sessionsRow).hidden : 'none') +
      ' design=' + (dotOf(designRow) ? dotOf(designRow).hidden : 'none'));

  const software = page.rows('.surfaces-section')
    .find((one) => one.dataset.group === 'software');
  const currentLanes = links.filter((one) => one.getAttribute('aria-current') === 'page')
    .map((one) => one.dataset.address);
  check('MAP the current lane lights its region bracket',
    !!software && software.dataset.current === 'true',
    (software ? 'current=' + software.dataset.current : 'no section') +
      ' hash=' + page.window.location.hash + ' lanes=' + currentLanes.join(','));

  const softwareHead = page.rows('.surfaces-group')
    .find((one) => one.closest('.surfaces-section') &&
      one.closest('.surfaces-section').dataset.group === 'software');
  // The fixture's counts doc says 1 need + 1 working: the sessions row shows
  // 2 (its own arithmetic), so the region badge totals 2.
  check('MAP the folded region still says what it holds',
    !!softwareHead && softwareHead.textContent.includes('2'),
    softwareHead ? softwareHead.textContent : 'no head');
  if (softwareHead) softwareHead.click();
  await flush(60);
  const folded = page.rows('.surfaces-section')
    .find((one) => one.dataset.group === 'software');
  check('MAP a region folds and remembers',
    !!folded && folded.dataset.folded === 'true' &&
      String(page.window.localStorage.getItem('fleet-rail-folded') || '').includes('software'),
    folded ? 'folded=' + folded.dataset.folded : 'no section');
}

// R6: the drawer's markdown body is marked's render, cleaned by DOMPurify.
// marked runs for real in this sandbox (pure JS); the sanitiser is a
// recorder here because it needs a real DOM — the live probe proves the
// stripping, this proves the wiring and the parser's output.
async function theDrawerRendersMarkdownThroughTheEngine() {
  const mdText = [
    '# The brief',
    '',
    'A line with **bold** and `code`.',
    '',
    '1. first',
    '2. second',
    '',
    '- one',
    '  - nested',
    '',
    '> a quote',
    '',
    '| a | b |',
    '|---|---|',
    '| 1 | 2 |',
    '',
    '![shot](shot.png)',
    '',
    '```sh',
    'fleet release',
    '```',
    '',
    '<script>window.__pwned = 1</script>',
    '<img src="x.png" onerror="window.__pwned = 2">',
    ''
  ].join('\n');
  const page = boot({ hash: '#/sessions/md-1', documents: {
    sessions: {
      type: 'sessions', read_at: 'now', current: '',
      counts: { needs: 0, working: 0, background: 0, earlier: 1, total: 1 },
      sessions: [row('md-1', 'completed', { title: 'a run that wrote a brief' })],
    },
    state: (asked) => ({
      ...emptyState(asked), session: asked,
      events: [{ type: 'message', role: 'owner', text: 'open the brief' }],
    }),
    files: {
      'docs/brief.md': { type: 'file', path: 'docs/brief.md', name: 'brief.md',
        language: 'markdown', bytes: 512, text: mdText },
    },
  } });
  await flush();
  page.open();
  await flush(60);
  page.push({ type: 'tool_call', tool: 'send_file', summary: 'the brief',
    arguments: JSON.stringify({ path: 'docs/brief.md' }) });
  await flush(20);
  page.push({ type: 'tool_result', tool: 'send_file', approved: true,
    preview: 'handed over docs/brief.md' });
  await flush(40);
  const chips = page.rows('.preview-chip')
    .filter((one) => one.textContent.trim() === 'brief.md');
  check('MDK the brief chip opens the file', chips.length === 1, String(chips.length));
  if (chips[0]) chips[0].click();
  await flush(60);

  const clean = String(page.window.__sanitized || '');
  check('MDK the sanitiser was handed the engine\u2019s own HTML',
    clean.indexOf('<h1>') !== -1 && clean.indexOf('<ol>') !== -1 &&
      clean.indexOf('<blockquote>') !== -1 && clean.indexOf('<table>') !== -1 &&
      clean.indexOf('<pre>') !== -1 && clean.indexOf('<img') !== -1,
    clean.slice(0, 120));
  check('MDK the untrusted payload reached the sanitiser, not the DOM directly',
    clean.indexOf('<script>') !== -1 && /onerror=/.test(clean),
    clean.slice(-160));
}

