// The drawer opens the object it is (the UX map study, 2026-11-23): a kind
// table over the language the file read returns — code files and trees in
// the code body, markdown and every binary document in the rendered body —
// with the mode switch as the per-object override, never a default that
// leaks into the next object. The read body also opens with its relevance
// line: what the object is, and the sibling body one press away.
async function theDrawerOpensTheObjectItIs() {
  const page = boot({ hash: '#/sessions/kind-1', documents: {
    sessions: {
      type: 'sessions', read_at: 'now', current: '',
      counts: { needs: 0, working: 0, background: 0, earlier: 1, total: 1 },
      sessions: [row('kind-1', 'completed', { title: 'a run that handed over files' })],
    },
    state: (asked) => ({
      ...emptyState(asked), session: asked,
      events: [{ type: 'message', role: 'owner', text: 'open the files' }],
    }),
    files: {
      'notes/b.md': { type: 'file', path: 'notes/b.md', name: 'b.md',
        language: 'markdown', bytes: 4, text: '# hi' },
      'src/a.rs': { type: 'file', path: 'src/a.rs', name: 'a.rs',
        language: 'rust', bytes: 21, text: 'fn main() {}' },
      'shots/x.png': { type: 'file', path: 'shots/x.png', name: 'x.png',
        language: 'png', bytes: 2048 },
      'docs/brief.docx': { type: 'file', path: 'docs/brief.docx', name: 'brief.docx',
        language: 'docx', bytes: 5120, text: null },
    },
  } });
  await flush();
  page.open();
  await flush(60);

  const mode = () => ['document', 'code', 'preview', 'web']
    .filter((m) => page.IDS['read-mode-' + m] &&
      page.IDS['read-mode-' + m].classList.contains('on'))
    .join(',');
  const openVia = async (path) => {
    page.push({ type: 'tool_call', tool: 'send_file', summary: path,
      arguments: JSON.stringify({ path: path }) });
    await flush(20);
    page.push({ type: 'tool_result', tool: 'send_file', approved: true,
      preview: 'handed over ' + path });
    await flush(40);
    const chips = page.rows('.preview-chip')
      .filter((one) => one.textContent.trim() === path.split('/').pop());
    const chip = chips[chips.length - 1];
    check('KIND the ' + path + ' chip opens the file', !!chip, 'no chip');
    if (chip) chip.click();
    await flush(40);
  };

  await openVia('notes/b.md');
  check('KIND markdown opens the rendered body', mode() === 'preview', mode());
  check('KIND the line names the kind and the size',
    page.text('pane-rel-what') === 'markdown \u00b7 4 B',
    page.text('pane-rel-what'));
  const press = page.IDS['pane-rel-press'];
  check('KIND the line suggests the sibling body',
    !!press && press.hidden !== true && press.textContent === 'read as code',
    press ? String(press.hidden) + ' / ' + press.textContent : 'no press');
  press.click();
  await flush(40);
  check('KIND the press overrides the body for this object',
    mode() === 'code' && page.IDS['pane-rel-press'].textContent === 'read as preview',
    mode() + ' / ' + page.IDS['pane-rel-press'].textContent);

  await openVia('src/a.rs');
  check('KIND a code file opens the code body', mode() === 'code', mode());
  check('KIND the override did not leak into the next object',
    page.text('pane-rel-what') === 'rust \u00b7 21 B', page.text('pane-rel-what'));

  await openVia('shots/x.png');
  check('KIND an image opens the rendered body', mode() === 'preview', mode());
  check('KIND the line reads the image\u2019s own size',
    page.text('pane-rel-what') === 'png \u00b7 2.0 kB', page.text('pane-rel-what'));

  await openVia('docs/brief.docx');
  check('KIND a docx opens the rendered body', mode() === 'preview', mode());
  check('KIND the line reads the document\u2019s kind and size',
    page.text('pane-rel-what') === 'docx \u00b7 5.0 kB', page.text('pane-rel-what'));
}

// R7: the committed workbook renders through the face's own reader — the
// zip's central directory, styles.xml, the sheet's sparse cells — and the
// assertions read the rendered table, not the source. The fixture is
// tests/face/fixtures/release-ledger.xlsx (make-fixtures.mjs writes it;
// LibreOffice reads it as a workbook, so it is not app-shaped XML only).
async function theSheetRendersItsOwnForm() {
  const path = 'ledgers/release-ledger.xlsx';
  const page = boot({ hash: '#/sessions/kind-sheet', documents: {
    sessions: {
      type: 'sessions', read_at: 'now', current: '',
      counts: { needs: 0, working: 0, background: 0, earlier: 1, total: 1 },
      sessions: [row('kind-sheet', 'completed', { title: 'the ledger was handed over' })],
    },
    state: (asked) => ({
      ...emptyState(asked), session: asked,
      events: [{ type: 'message', role: 'owner', text: 'open the ledger' }],
    }),
    files: {
      [path]: { type: 'file', path: path, name: 'release-ledger.xlsx',
        language: 'xlsx', bytes: FIXTURE_SHEET.length, text: null },
    },
    previewBytes: { [path]: FIXTURE_SHEET },
  } });
  await flush();
  page.open();
  await flush(60);
  page.push({ type: 'tool_call', tool: 'send_file', summary: path,
    arguments: JSON.stringify({ path: path }) });
  await flush(20);
  page.push({ type: 'tool_result', tool: 'send_file', approved: true,
    preview: 'handed over the ledger' });
  await flush(40);
  const chips = page.rows('.preview-chip')
    .filter((one) => one.textContent.trim() === 'release-ledger.xlsx');
  const chip = chips[chips.length - 1];
  check('XLSXF the committed workbook opens through its receipt', !!chip, 'no chip');
  if (chip) chip.click();
  await flush(120);
  await settle();

  const cells = () => page.rows('.pane-data td');
  const title = cells()[0];
  check('XLSXF the merged title spans the sheet',
    !!title && title.textContent === 'the release ledger' &&
      title.getAttribute('colspan') === '4' && title.className.includes('bold'),
    title ? title.textContent + ' / ' + title.getAttribute('colspan') + ' / ' + title.className : 'no cell');
  const header = cells().slice(1, 5);
  check('XLSXF the header keeps its weight',
    header.length === 4 && header.every((td) => td.className.includes('bold')),
    header.map((td) => td.className).join(' | '));
  const dated = cells().find((td) => td.className.includes('date'));
  check('XLSXF an Excel serial reads as its date',
    !!dated && dated.textContent === '2026-11-20',
    dated ? dated.textContent : 'no date cell');
  const grouped = cells().find((td) => td.textContent === '41,208,112');
  check('XLSXF a grouped number keeps its form and its alignment',
    !!grouped && grouped.className.includes('num'),
    grouped ? grouped.className : 'no grouped cell');
  check('XLSXF a percentage keeps its form',
    cells().some((td) => td.textContent === '12.5%'),
    cells().map((td) => td.textContent).join(' | '));
  check('XLSXF an inline string is not blank',
    cells().some((td) => td.textContent === 'fleet-windows-x64.zip'),
    cells().map((td) => td.textContent).join(' | '));
  const cols = page.rows('.pane-xlsx col');
  check('XLSXF the columns keep the widths the sheet declares',
    cols.length === 4 && parseFloat(cols[0].style.width) > 7.4 &&
      parseFloat(cols[0].style.width) < 7.5,
    cols.map((col) => col.style.width).join(' | '));
  check('XLSXF the pane says what it did and did not do',
    page.text('pane-preview-body').includes('the sheet\u2019s own form') &&
      page.text('pane-preview-body').includes('formulas are shown as their cached values') &&
      page.text('pane-preview-body').includes('charts are not part of this preview'),
    page.text('pane-preview-body').slice(0, 120));

  // The second sheet carries 501 rows, so the cap has something to say.
  const tabs = page.rows('.pane-xlsx-tab');
  check('XLSXF the workbook\u2019s sheets are its tabs', tabs.length === 2,
    tabs.map((tab) => tab.textContent).join(' | '));
  if (tabs[1]) tabs[1].click();
  await flush(120);
  await settle();
  check('XLSXF the row cap says so',
    page.text('pane-preview-body').includes('the first 500 of 501 rows'),
    page.text('pane-preview-body').slice(0, 120));
  check('XLSXF the cap still renders 500 rows',
    page.rows('.pane-data tr').length === 500,
    String(page.rows('.pane-data tr').length));
}

// R8: the committed deck that cannot be parsed (tests/face/fixtures/
// broken-deck.pptx — a zip that is not an Office Open XML package) mounts
// in the sandboxed frame with the bundle and its bytes inlined; the
// frame's own report decides — a refusal lands the text outline BY NAME
// with the viewer's reason, a render leaves the slides alone. The viewer
// itself runs only in a browser, which is why the frame speaks here
// through fromFrame: the message contract, the nonce, the state tag and
// the fallback are the face's. The reason used below is the one the live
// face reported for these exact bytes ("The archive is not an Office Open
// XML package ([Content_Types].xml missing).").
async function theDeckFallsBackToTheOutlineByName() {
  const path = 'decks/broken-deck.pptx';
  const page = boot({ hash: '#/sessions/kind-deck', documents: {
    sessions: {
      type: 'sessions', read_at: 'now', current: '',
      counts: { needs: 0, working: 0, background: 0, earlier: 1, total: 1 },
      sessions: [row('kind-deck', 'completed', { title: 'the deck was handed over' })],
    },
    state: (asked) => ({
      ...emptyState(asked), session: asked,
      events: [{ type: 'message', role: 'owner', text: 'open the deck' }],
    }),
    files: {
      [path]: { type: 'file', path: path, name: 'broken-deck.pptx',
        language: 'pptx', bytes: FIXTURE_DECK.length, text: null },
    },
    previewBytes: { [path]: FIXTURE_DECK },
  } });
  await flush();
  page.open();
  await flush(60);
  const openVia = async () => {
    page.push({ type: 'tool_call', tool: 'send_file', summary: path,
      arguments: JSON.stringify({ path: path }) });
    await flush(20);
    page.push({ type: 'tool_result', tool: 'send_file', approved: true,
      preview: 'handed over the deck' });
    await flush(40);
    const chips = page.rows('.preview-chip')
      .filter((one) => one.textContent.trim() === 'broken-deck.pptx');
    const chip = chips[chips.length - 1];
    check('PPTXF the committed deck opens through its receipt', !!chip, 'no chip');
    if (chip) chip.click();
    await flush(120);
    await settle();
  };

  await openVia();
  const frame = page.rows('.pane-doc-frame')[0];
  const srcdoc = frame ? String(frame.srcdoc) : '';
  check('PPTXF the deck mounts inside the sandboxed frame',
    !!frame && frame.getAttribute('sandbox') === 'allow-scripts' &&
      srcdoc.includes('new PPTXjs.PptxViewer("#slides"') &&
      srcdoc.includes(FIXTURE_DECK.toString('base64')),
    frame ? String(frame.getAttribute('sandbox')) + ' / ' + srcdoc.length : 'no frame');
  check('PPTXF the viewer bundle is served from the face\u2019s own route',
    page.calls.some((one) => one.url === '/vendor/pptxjs.umd.js'),
    page.calls.map((one) => one.url).filter((one) => one.includes('vendor')).join(' | '));
  const nonce = (srcdoc.match(/var N = "([^"]+)"/) || [])[1];
  check('PPTXF the frame reports through its own nonce', !!nonce, String(nonce));

  // The wrap the mount made: the fallback replaces the pane's contents, so
  // the state tag is read on the mounted element (the state a browser
  // shows while the outline is read) rather than on the outline's own.
  const mounted = page.rows('.pane-pptx')[0];
  const refused = 'The archive is not an Office Open XML package ([Content_Types].xml missing).';
  page.fromFrame(page.frames.indexOf(frame), { nonce: nonce, type: 'pptx-failed',
    reason: refused });
  await flush(40);
  await settle();
  check('PPTXF a viewer that refuses lands the outline and names the reason',
    !!mounted && mounted.dataset.state === 'failed' &&
      page.text('pane-preview-body').includes('0 slides \u00b7 the text outline') &&
      page.text('pane-preview-body').includes('the slide renderer reported: ' + refused) &&
      page.text('pane-preview-body').includes('the deck itself did not render here'),
    page.text('pane-preview-body').slice(0, 160));

  // A second open, and the frame's other report: the slides stand and no
  // outline is drawn over them.
  await openVia();
  const again = page.rows('.pane-doc-frame')[0];
  const nonce2 = (String(again && again.srcdoc).match(/var N = "([^"]+)"/) || [])[1];
  page.fromFrame(page.frames.indexOf(again), { nonce: nonce2, type: 'pptx-rendered' });
  await flush(40);
  const drawn = page.rows('.pane-pptx')[0];
  check('PPTXF a rendered deck says so and draws no outline',
    !!drawn && drawn.dataset.state === 'rendered' &&
      !page.text('pane-preview-body').includes('the text outline'),
    drawn ? drawn.dataset.state : 'no wrap');
}

// New mints a real conversation at the press (the owner's 2026-11-05
// ruling, replacing N2's create-then-send): the log exists before any
// words, so the send that follows can only name this conversation —
// never an older active one. An abandoned compose leaves the shell; the
// intent fallback survives only for a refused creation.
async function newMintsImmediatelyAndTheSendNamesIt() {
  const doc = {
    sessions: {
      type: 'sessions', read_at: 'now', current: 'x-1',
      counts: { needs: 0, working: 0, background: 0, earlier: 1, total: 1 },
      sessions: [row('x-1', 'completed', { title: 'the existing conversation' })],
    },
    state: (asked) => ({ ...emptyState(asked), session: asked }),
  };
  const page = boot({
    width: 1440, hash: '#/sessions/x-1',
    storage: { 'fleet-draft-new': 'pending words' },
    documents: doc,
  });
  await flush();
  page.open();
  await flush(80);
  const news = () => page.calls.filter((c) => c.url.startsWith('/api/session/new'));
  page.fireOn('conv-new', 'click');
  await flush(40);
  check('NEW mints at the press',
    news().length === 1 && page.window.location.hash === '#/sessions',
    news().length + ' / ' + page.window.location.hash);
  check('the pending draft returns', page.IDS.task.value === 'pending words',
    JSON.stringify(page.IDS.task.value));
  check('the welcome shows the fresh compose',
    page.IDS.empty.hidden === false && page.IDS.log.hidden === true,
    'empty hidden: ' + page.IDS.empty.hidden);
  // The send names the minted conversation: one create total, and the
  // run never falls to the older one.
  page.IDS.task.value = 'the first words';
  page.fireOn('composer', 'submit', {});
  await flush(80);
  check('the send creates no second session', news().length === 1,
    String(news().length));
  const runs = page.calls.filter((c) => c.url.startsWith('/api/run'));
  check('the run lands in the conversation New minted',
    runs.length === 1 && String(runs[0].url).includes('session=new-session-1'),
    JSON.stringify(runs.map((c) => c.url)));
  check('the run never names the older conversation',
    !runs.some((c) => String(c.url).includes('x-1')),
    JSON.stringify(runs.map((c) => c.url)));
  // Abandon: opening the existing conversation mints nothing more —
  // the shell from the press stands in the archive.
  page.window.location.hash = '#/sessions/x-1';
  await flush(80);
  check('abandoning mints nothing more', news().length === 1,
    String(news().length));
}

// The 2026-11-05 regression, pinned at its sharpest: a send typed while
// another conversation's run works dispatches into the conversation it
// was typed for — the one New minted — and never into the working one.
async function aSendBesideARunMintsAndNamesItsOwnConversation() {
  const doc = {
    sessions: {
      type: 'sessions', read_at: 'now', current: 'old-a',
      counts: { needs: 0, working: 1, background: 0, earlier: 1, total: 2 },
      sessions: [
        row('old-a', 'working', { title: 'the active conversation' }),
        row('old-b', 'completed', { title: 'an earlier one' }),
      ],
    },
    state: (asked) => ({
      ...emptyState(asked), session: asked,
      running: true, driving: 'old-a',
    }),
  };
  const page = boot({
    width: 1440, hash: '#/sessions/old-a', documents: doc, newId: 'fresh-c',
  });
  await flush();
  page.open();
  await flush(80);
  page.fireOn('conv-new', 'click');
  await flush(80);
  const news = page.calls.filter((c) => c.url.startsWith('/api/session/new'));
  check('REG the + mints the new conversation', news.length === 1,
    String(news.length));
  page.IDS.task.value = 'the words for the new one';
  page.fireOn('composer', 'submit', {});
  await flush(80);
  const runs = page.calls.filter((c) => c.url.startsWith('/api/run'));
  check('REG the send dispatches behind no foreign run',
    runs.length === 1, JSON.stringify(runs.map((c) => c.url)));
  check('REG the run names the minted conversation',
    runs.length === 1 && String(runs[0].url).includes('session=fresh-c'),
    JSON.stringify(runs.map((c) => c.url)));
  check('REG never the older active session',
    !runs.some((c) => String(c.url).includes('old-a')),
    JSON.stringify(runs.map((c) => c.url)));
}

// The queue's own half of the same ruling: a message queued on one
// conversation while another's run works keeps ITS conversation across
// the flush — even when the face has opened a different one by the time
// the working run ends.
async function aQueuedFlushNamesItsOwnConversation() {
  const doc = {
    sessions: {
      type: 'sessions', read_at: 'now', current: 'old-b',
      counts: { needs: 0, working: 1, background: 0, earlier: 1, total: 2 },
      sessions: [
        row('old-a', 'working', { title: 'the active conversation' }),
        row('old-b', 'completed', { title: 'the one being written' }),
      ],
    },
    state: (asked) => ({
      ...emptyState(asked), session: asked,
      running: true, driving: 'old-a',
    }),
  };
  const page = boot({
    width: 1440, hash: '#/sessions/old-b', documents: doc,
  });
  await flush();
  page.open();
  await flush(80);
  // Typed on old-b while old-a works: the send queues, and the chip
  // says which conversation it belongs to.
  page.IDS.task.value = 'the words for old-b';
  page.fireOn('composer', 'submit', {});
  await flush(80);
  const queuedRuns = page.calls.filter((c) => c.url.startsWith('/api/run'));
  check('REG a send behind a foreign run queues instead of dispatching',
    queuedRuns.length === 0 && page.IDS['queue-chip'] && !page.IDS['queue-chip'].hidden,
    JSON.stringify(queuedRuns.map((c) => c.url)));
  // The owner opens the working conversation before its run ends.
  page.window.location.hash = '#/sessions/old-a';
  await flush(80);
  // The working run ends: the queue drains — into old-b, where the
  // message was typed, not into the conversation now on screen.
  page.push({ type: 'finished', session: 'old-a', stop_reason: 'handed back' });
  await flush(80);
  const runs = page.calls.filter((c) => c.url.startsWith('/api/run'));
  check('REG the flush dispatches the queued message',
    runs.length === 1, JSON.stringify(runs.map((c) => c.url)));
  check('REG the flush names the conversation it was typed for',
    runs.length === 1 && String(runs[0].url).includes('session=old-b'),
    JSON.stringify(runs.map((c) => c.url)));
}

// KI-495 (the owner's report): with a message queued, the send button
// did nothing. Two shapes carry it. First, the idle press: a queue can
// outlive the run that made it — a state read that says idle while the
// queue still waits — and Send must dispatch the head rather than try
// to queue an empty composer. Second, a face that attached to a
// running chat has no process card until a process event lands, and
// the Stop it shows must actually stop.
async function aQueuedMessageSendsFromTheIdleButton() {
  let phase = 0;
  const page = boot({
    hash: '#/chat',
    documents: {
      state: (asked) => ({
        ...emptyState(asked), session: asked,
        running: phase === 0,
        driving: phase === 0 ? asked : '',
      }),
    },
  });
  await flush();
  page.open();
  await flush();
  // While the run works, a send queues.
  page.IDS.task.value = 'the queued words';
  page.fireOn('composer', 'submit', {});
  await flush();
  check('KI-495 the send behind the run queues',
    page.text('queue-count').includes('1'), page.text('queue-count'));
  check('KI-495 no run started while the queue waited',
    page.calls.filter((c) => c.url.startsWith('/api/run')).length === 0);
  // The run is over (a state read says so) and the queue still waits.
  phase = 1;
  page.open();
  await flush();
  const before = page.calls.filter((c) => c.url.startsWith('/api/run')).length;
  page.fireOn('send', 'click', {});
  await flush();
  const runs = page.calls.filter((c) => c.url.startsWith('/api/run'));
  check('KI-495 the idle Send dispatches the queued message',
    runs.length === before + 1, JSON.stringify(page.calls.map((c) => c.url)));
  check('KI-495 the dispatched run carries the queued words',
    runs.length === before + 1 && String(runs[runs.length - 1].body || '').includes('the queued words'),
    JSON.stringify(runs.map((c) => c.body)));
  check('KI-495 the queue is empty after the press',
    page.IDS['queue-chip'].hidden === true, page.IDS['queue-count'].textContent);
}

async function aStopWorksWithoutAProcessCard() {
  const page = boot({
    hash: '#/chat',
    documents: {
      state: (asked) => ({ ...emptyState(asked), session: asked, running: true, driving: asked }),
    },
  });
  await flush();
  page.open();
  await flush();
  const send = page.IDS.send;
  // The composer's button queues while a run is in flight — never a
  // hidden stop the owner's press trips over; the stop lives on the
  // working line, beside the state it ends.
  check('KI-495 a running chat keeps the button Send in queue mode',
    send.dataset.mode === 'queue' &&
      send.getAttribute('aria-label') === 'queue the task; it sends when the run ends',
    JSON.stringify({ mode: send.dataset.mode, label: send.getAttribute('aria-label') }));
  check('KI-495 the working line carries the stop',
    page.IDS['working-stop'].hidden === false && page.IDS['working-stop'].disabled === false,
    'hidden=' + page.IDS['working-stop'].hidden + ' disabled=' + page.IDS['working-stop'].disabled);
  // The press queues the typed words; nothing dispatches.
  page.IDS.task.value = 'the words for later';
  page.fireOn('send', 'click', {});
  await flush();
  check('KI-495 the press queues while a run is in flight',
    page.IDS['queue-chip'].hidden === false && page.IDS.task.value === '',
    'chip=' + page.IDS['queue-chip'].hidden + ' task=' + JSON.stringify(page.IDS.task.value));
  check('KI-495 the queued press dispatches nothing',
    page.calls.every((c) => c.url !== '/api/run'),
    JSON.stringify(page.calls.map((c) => c.url)));
  // The stop works from the working line without a process card (the
  // state read alone tells the face a run is in flight).
  const before = page.calls.filter((c) => c.url === '/api/stop').length;
  page.fireOn('working-stop', 'click', {});
  await flush();
  const stops = page.calls.filter((c) => c.url === '/api/stop').length;
  check('KI-495 the working-line stop reaches the bridge',
    stops === before + 1, JSON.stringify(page.calls.map((c) => c.url)));
}

// RE (the reload-reattach plan): a reload restores what was showing.
// The conversation the face held is remembered across reloads — written
// wherever a real conversation binds, cleared by the deliberate detach —
// and the chat address re-attaches through the same seed the work row
// runs.
async function theOpenConversationIsRemembered() {
  const doc = {
    sessions: {
      type: 'sessions', read_at: 'now', current: 'held-1',
      counts: { needs: 0, working: 0, background: 0, earlier: 1, total: 1 },
      sessions: [row('held-1', 'completed', { title: 'the held conversation' })],
    },
    state: (asked) => ({ ...emptyState(asked), session: asked }),
  };
  const page = boot({
    width: 1440, hash: '#/sessions/held-1', documents: doc, newId: 'mint-1',
  });
  await flush();
  page.open();
  await flush(80);
  const key = () => page.window.localStorage.getItem('fleet-open-session');
  check('RE the open conversation is remembered', key() === 'held-1', String(key()));
  // The + mints and rebinds the memory to the minted conversation.
  page.fireOn('conv-new', 'click');
  await flush(80);
  check('RE the mint rebinds the memory', key() === 'mint-1', String(key()));
  // Opening the older conversation rebinds again.
  page.window.location.hash = '#/sessions/held-1';
  await flush(80);
  check('RE opening rebinds the memory', key() === 'held-1', String(key()));
  // The deliberate home walk clears it: the welcome the owner chose
  // stays a welcome across reloads.
  page.window.location.hash = '#/chat';
  await flush(80);
  check('RE the deliberate detach clears the memory', key() === null, String(key()));
}

