// The owner's 2026-11-16 black-hole report: a run kept going at the
// bridge while the owner looked elsewhere; its row read "working" and the
// chat stream never came back. Returning to a driven conversation must go
// through the resume and reattach the transcript — never answer an empty
// box over a live run.
async function aDrivenConversationReattachesWhenTheOwnerComesBack() {
  const page = boot({
    hash: '#/sessions/open-1',
    documents: {
      sessions: {
        type: 'sessions', read_at: 'now', current: '',
        counts: { needs: 0, working: 1, background: 0, earlier: 0, total: 1 },
        sessions: [row('open-1', 'working', { title: 'the black hole' })],
      },
      state: (asked) => ({
        ...emptyState(asked),
        session: 'open-1',
        running: true,
        driving: 'open-1',
        events: [{ type: 'message', role: 'owner', text: 'build the black hole' }],
      }),
    },
  });
  await flush();
  page.open();
  await flush(40);
  check('REATTACH the run opens with its transcript',
    page.IDS.log.hidden === false && page.text('log').includes('build the black hole'),
    'log hidden=' + page.IDS.log.hidden);

  // The owner looks elsewhere: the threads lens detaches the view.
  page.window.location.hash = '#/chat';
  await flush(80);
  check('REATTACH the threads lens detaches the view',
    page.IDS.log.hidden === true, 'log hidden=' + page.IDS.log.hidden);

  // Coming back through the route: the resume must run and the transcript
  // must return.
  const before = page.calls.filter((c) => c.url.startsWith('/api/resume')).length;
  page.window.location.hash = '#/sessions/open-1';
  await flush(120);
  const resumed = page.calls.filter((c) => c.url.startsWith('/api/resume')).length;
  check('REATTACH the return resumes the session', resumed > before, before + ' -> ' + resumed);
  check('REATTACH the transcript is back',
    page.IDS.log.hidden === false && page.text('log').includes('build the black hole'),
    'log hidden=' + page.IDS.log.hidden + ' text=' + page.text('log').slice(0, 80));
}

// The composer's microphone (the dictation plan): one press starts a
// recording on the server, the second stops it, and the transcript lands
// where the caret was. The server records — a page never opens the mic.
async function theComposerDictatesIntoTheBox() {
  const page = boot({
    documents: { state: (asked) => emptyState(asked) },
    reply: { transcript: 'hello from the mic', duration_ms: 1234 },
  });
  await flush();
  page.open();
  await flush(40);
  // The mic is `/dictate` now (P1: the button retired into the command).
  // The command's discoverability is the type-ahead, so the case opens it
  // the way the owner does — `/dict` and the list names the verb.
  page.IDS.task.value = '/dict';
  page.fireOn('task', 'input');
  await flush(40);
  const offered = [...page.IDS.commands.children]
    .map((one) => String(one.textContent || ''));
  check('MIC the dictation door is the /dictate command',
    offered.some((one) => one.includes('/dictate')), offered.join(' | '));
  page.fireOn('task', 'keydown', { key: 'Escape' });
  runSlash(page, '/dictate');
  await flush();
  check('MIC the press starts a recording',
    page.calls.some((c) => c.method === 'POST' && c.url === '/api/dictate/start'),
    JSON.stringify(page.calls.map((c) => c.url)));
  check('MIC the composer says it is listening while it records',
    /listening/.test(page.text('hint')) &&
      page.IDS.composer.dataset.dictation === 'listening',
    page.text('hint') + ' / ' + page.IDS.composer.dataset.dictation);
  runSlash(page, '/dictate');
  await flush(40);
  check('MIC the second press stops and transcribes',
    page.calls.some((c) => c.method === 'POST' && c.url === '/api/dictate/stop'),
    JSON.stringify(page.calls.map((c) => c.url)));
  check('MIC the words land in the composer',
    page.IDS.task.value.indexOf('hello from the mic') !== -1,
    page.IDS.task.value);
  check('MIC the composer returns to its idle line',
    page.text('hint').includes('Shift+Enter makes a newline'),
    page.text('hint'));
}

// The owner's 2026-11-16 point: the door belongs in the composer, and the
// landing is where a conversation starts — so the same door there starts
// one with its bots instead of refusing for the lack of a session.
