// The queued messages carry their three verbs as icons — send to the
// head, edit back into the composer, drop out — the reply footer's own
// approach, with the words as tooltips and accessible names.
async function theQueuedMessagesCarryTheirActions() {
  const page = boot({
    width: 1440,
    hash: '#/sessions/this-one',
    documents: {
      sessions: {
        type: 'sessions', read_at: 'now', current: '',
        counts: { needs: 0, working: 0, background: 0, earlier: 2, total: 2 },
        sessions: [
          row('other-one', 'working', { title: 'corpus-refresh-fleet — approval' }),
          row('this-one', 'completed', { title: 'this conversation' }),
        ],
      },
      // This chat's own run is in flight, so a further send here queues
      // (a send in ANOTHER conversation now dispatches concurrently — the
      // multi-session plan's Stage 2 — and is pinned by its own case).
      state: (asked) => ({ ...emptyState(asked), session: asked, driving: asked, running: true }),
    },
  });
  await flush();
  page.open();
  await flush();
  page.IDS.task.value = 'the first queued';
  page.fireOn('composer', 'submit', {});
  await flush();
  page.IDS.task.value = 'the second queued';
  page.fireOn('composer', 'submit', {});
  await flush();
  const rows = () => page.rows('.queue-row');
  check('Q two messages queued', rows().length === 2, String(rows().length));
  // The head's send is "send now" — active, it stops the run in flight
  // and the message sends the moment the run ends. Below the head, send
  // moves the message to the head. The head is never a dead button.
  check('Q each row carries the three icon verbs with the head active',
    rows().every((r) => r.querySelectorAll('.queue-send').length === 1 &&
        r.querySelectorAll('.queue-edit').length === 1 &&
        r.querySelectorAll('.queue-drop').length === 1) &&
      rows()[0].querySelector('.queue-send').disabled === false &&
      rows()[0].querySelector('.queue-send').getAttribute('aria-label') === 'send now' &&
      rows()[1].querySelector('.queue-send').disabled === false &&
      rows()[1].querySelector('.queue-send').getAttribute('aria-label') === 'send first',
    JSON.stringify(rows().map((r) => ({
      send: r.querySelector('.queue-send').disabled,
      name: r.querySelector('.queue-send').getAttribute('aria-label'),
    }))));
  // Send now on the head: the run in flight stops (a tool call running
  // finishes first) and the finished handler flushes the head.
  const stopsBefore = page.calls.filter((c) => c.url === '/api/stop').length;
  rows()[0].querySelector('.queue-send').click();
  await flush();
  check('Q send now stops the run in flight',
    page.calls.filter((c) => c.url === '/api/stop').length === stopsBefore + 1,
    JSON.stringify(page.calls.map((c) => c.url)));
  check('Q send now keeps the queue waiting for the end',
    rows().length === 2 && rows()[0].querySelector('.queue-text').textContent === 'the first queued',
    rows()[0].querySelector('.queue-text').textContent);
  // Send on the second moves it to the head — the head is what the next
  // run sends.
  rows()[1].querySelector('.queue-send').click();
  await flush();
  check('Q send moves the message to the head',
    rows()[0].querySelector('.queue-text').textContent === 'the second queued',
    rows()[0].querySelector('.queue-text').textContent);
  // Edit returns the words to the composer and takes the row out.
  rows()[0].querySelector('.queue-edit').click();
  await flush();
  check('Q edit returns the words to the composer',
    page.IDS.task.value === 'the second queued' && rows().length === 1,
    JSON.stringify(page.IDS.task.value) + ' / ' + rows().length);
  // Drop removes what is left, and the chip hides with an empty queue.
  rows()[0].querySelector('.queue-drop').click();
  await flush();
  check('Q drop empties the queue and hides the chip',
    rows().length === 0 && page.IDS['queue-chip'].hidden === true,
    String(rows().length));
  // The text never outgrows the row: the flex item shrinks to it (the
  // auto minimum is what pushed a long message past the composer) and
  // the row contains what is left.
  check('Q the queue text shrinks to the row, never past the composer',
    ruleBlock('.queue-text').includes('min-width: 0') &&
      ruleBlock('.queue-row').includes('overflow: hidden') &&
      ruleBlock('.queue-row').includes('gap: 8px'),
    ruleBlock('.queue-text') + ' | ' + ruleBlock('.queue-row'));
}


// gui-revamp C13: the diff offers both verdicts per hunk, and the accept
// sends the *reviewed hunk* back — its blocks and the context the review
// showed — because a decision changes what a fresh diff would number.
async function theDiffOffersBothVerdictsPerHunk() {
  const diff = {
    type: 'diff', turn: 1,
    files: [{
      path: 'f.txt', kind: 'modified', too_large: false,
      hunks: [{
        old: ['four'], new: ['FOUR'], new_at: 3,
        before_old: ['one', 'two', 'three'], after_old: [],
        before_new: ['one', 'TWO', 'three'], after_new: [],
      }],
    }],
  };
  const page = boot({
    width: 1440,
    hash: '#/chat',
    documents: { diff, state: (asked) => emptyState(asked) },
  });
  await flush();
  page.open();
  await flush();
  // The review is the composer's slash command.
  page.IDS.task.value = '/review';
  page.IDS.task.fire('keydown', { key: 'Enter', shiftKey: false });
  await flush(200);
  const accept = page.rows('.replay-button')
    .filter((one) => String(one.textContent).trim() === 'accept this hunk');
  const reject = page.rows('.replay-button')
    .filter((one) => String(one.textContent).trim() === 'reject this hunk');
  check('REV each hunk offers both verdicts',
    accept.length === 1 && reject.length === 1,
    accept.length + ' accept / ' + reject.length + ' reject');
  accept[0].click();
  await flush(160);
  const posted = page.calls.filter((c) => c.method === 'POST' && c.url === '/api/diff/accept');
  check('REV the accept sends the reviewed hunk',
    posted.length === 1 && String(posted[0].body).includes('"old":["four"]') &&
      String(posted[0].body).includes('"new":["FOUR"]') &&
      String(posted[0].body).includes('"before_old":["one","two","three"]'),
    JSON.stringify(posted.map((c) => c.body)));
}

// conversation-control C3/C8: the queue is an ordered list the owner
// moves (a drag lands the row where it was dropped), the run ending
// drains the head, and a live turn's rewind stays hidden until its run
// is over.
async function theQueueReordersByDragAndDrainsWhenTheRunEnds() {
  const page = boot({
    width: 1440,
    hash: '#/sessions/this-one',
    documents: {
      sessions: {
        type: 'sessions', read_at: 'now', current: 'this-one',
        counts: { needs: 0, working: 1, background: 0, earlier: 0, total: 1 },
        sessions: [row('this-one', 'working', { title: 'this conversation' })],
      },
      state: (asked) => ({ ...emptyState(asked), session: asked,
        driving: 'this-one', running: true }),
    },
  });
  await flush();
  page.open();
  await flush();
  // Bind the conversation first: the reducer reads every event against
  // the session it belongs to, and the turn is what makes the run live.
  page.push({ type: 'session', session: 'this-one' });
  page.push({ type: 'turn', session: 'this-one', turn: 1 });
  page.push({ type: 'token', session: 'this-one', text: 'working' });
  await flush(80);
  // A run is in flight, so a send queues rather than starting one.
  const enqueue = async (text) => {
    page.IDS.task.value = text;
    page.fireOn('composer', 'submit', {});
    await flush();
  };
  await enqueue('one');
  await enqueue('two');
  await enqueue('three');
  const rows = () => page.rows('.queue-row');
  const texts = () => rows().map((r) => r.querySelector('.queue-text').textContent);
  // C9: the app opens on the conversation with the composer focused.
  check('C9 the composer holds the focus at boot', page.IDS.task.focused === true,
    String(page.IDS.task.focused));
  check('QCON three messages queue while the run works',
    texts().join(',') === 'one,two,three', texts().join(','));

  // C3: a drag lands the row where it was dropped. The dataTransfer is
  // the harness's own, carrying the source index the way the browser's
  // does.
  const transfer = {
    data: '0',
    effectAllowed: '',
    setData(key, value) { this.data = String(value); },
    getData() { return this.data; },
  };
  rows()[0].fire('dragstart', { dataTransfer: transfer });
  rows()[2].fire('drop', { preventDefault() {}, dataTransfer: transfer });
  await flush();
  check('QCON a drag moves the row to the drop position',
    texts().join(',') === 'two,three,one', texts().join(','));

  // The REAL browser sequence, which the drag above never exercises: a
  // browser fires `dragend` on the SOURCE row after the drop, and fires it
  // ALONE when the drag is cancelled or leaves the list. A `dragend` that
  // clears the source index unconditionally leaves the next drag with no
  // origin — the owner's report: the row looks moved while dragging and
  // does not land.
  const second = { data: '0', setData(k, v) { this.data = String(v); }, getData() { return this.data; } };
  rows()[2].fire('dragstart', { dataTransfer: second });
  rows()[2].fire('dragend', {});
  await flush();
  check('QCON a cancelled drag leaves the queue untouched',
    texts().join(',') === 'two,three,one', texts().join(','));
  // The full sequence on a fresh drag: start at the tail, land at the head,
  // with `dragend` after the drop exactly as the DOM spec orders it. The
  // queue is restored afterwards so the drain below keeps its own premise.
  const third = { data: '2', setData(k, v) { this.data = String(v); }, getData() { return this.data; } };
  rows()[2].fire('dragstart', { dataTransfer: third });
  rows()[0].fire('drop', { preventDefault() {}, dataTransfer: third });
  rows()[2].fire('dragend', {});
  await flush();
  check('QCON a drag with the full event sequence lands the row',
    texts().join(',') === 'one,two,three', texts().join(','));
  // Back to two,three,one — the state the drag test asserted and the drain
  // below expects — by the same verb the owner has.
  const fourth = { data: '0', setData(k, v) { this.data = String(v); }, getData() { return this.data; } };
  rows()[0].fire('dragstart', { dataTransfer: fourth });
  rows()[2].fire('drop', { preventDefault() {}, dataTransfer: fourth });
  rows()[0].fire('dragend', {});
  await flush();
  check('QCON the queue returns to the order the drain expects',
    texts().join(',') === 'two,three,one', texts().join(','));

  // A failure drains the head exactly as a finish does (C3): the head
  // leaves the queue and the composer takes its words. The dispatch it
  // starts is the send path's own pin.
  page.push({ type: 'failed', session: 'this-one', stop_reason: 'the run failed' });
  await flush(200);
  check('QCON the run failing drains the queue head',
    texts().join(',') === 'three,one', texts().join(','));

  // The owner's report, reproduced LAST so the probes above keep their own
  // premise: a drag whose dataTransfer carries the row's TEXT (a native
  // text-drag, which a `draggable` ancestor starts when the pointer goes
  // down on the row's own label) rather than our index. `dragIndex` is null
  // by then, so the handler falls back to `Number(getData(...))`, which is
  // NaN for a word, and RETURNS. The outline followed the cursor; nothing
  // lands. That is the owner's symptom exactly.
  const native = { data: 'one', setData(k, v) { this.data = String(v); }, getData() { return this.data; } };
  const queued = () => page.rows('.queue-row').map((r) => r.querySelector('.queue-text').textContent);
  const beforeNative = queued().join(',');
  const hadRows = page.rows('.queue-row');
  if (hadRows.length >= 2) {
    hadRows[1].fire('dragstart', { dataTransfer: native });
    hadRows[0].fire('dragend', {});
    hadRows[0].fire('drop', { preventDefault() {}, dataTransfer: native });
    await flush();
    check('QCON a drop carrying text instead of an index never silently no-ops',
      queued().join(',') !== beforeNative,
      'before=' + beforeNative + ' after=' + queued().join(','));
  }

  // The two halves the stub cannot see, and the reasons the case above
  // stays green while a real pointer drag does not land.
  //
  // (1) The label must not be selectable. The row is `draggable`, so a
  // pointer-down on a SELECTABLE label starts a native text-drag whose
  // DataTransfer carries the row's words instead of the handler's index —
  // and `Number('one')` is NaN, so the drop returns. The stub's own
  // `fire` never starts a text-drag, so it cannot fail this way.
  check('QCON the row label is not a text selection',
    /user-select:\s*none/.test(ruleBlock('.queue-text')),
    ruleBlock('.queue-text') || 'rule missing');
  // (2) The desktop window must not claim the drag for the webview. Tauri's
  // native drop handler is on by default (`drag_drop_handler_enabled:
  // true`), and while it is on an in-page row drop never reaches the row:
  // the row follows the cursor and nothing lands. Verified against the
  // pinned tauri 2.12.5 at
  // src-tauri/src/lib.rs — the builder must call the off switch.
  check('QCON the desktop window hands HTML5 drags to the page',
    /disable_drag_drop_handler\s*\(\s*\)/.test(RUST_TAURI),
    RUST_TAURI.includes('disable_drag_drop_handler')
      ? 'the call is present'
      : 'no disable_drag_drop_handler call in src-tauri/src/lib.rs');
}

// conversation-control C8: a live turn hides its rewind, and the run's
// end brings it back — the affordance describes an ended run.
async function aLiveTurnsRewindReturnsWhenTheRunEnds() {
  const page = boot({
    width: 1440,
    hash: '#/sessions/live-1',
    documents: {
      sessions: {
        type: 'sessions', read_at: 'now', current: 'live-1',
        counts: { needs: 0, working: 1, background: 0, earlier: 0, total: 1 },
        sessions: [row('live-1', 'working', { title: 'a live run' })],
      },
      state: (asked) => ({ ...emptyState(asked), session: asked,
        driving: 'live-1', running: true }),
    },
  });
  await flush();
  page.open();
  await flush();
  page.push({ type: 'turn', session: 'live-1', turn: 1 });
  page.push({ type: 'token', session: 'live-1', text: 'working on it' });
  await flush(120);
  const liveRows = () => page.rows('.row-rewind')
    .filter((one) => one.dataset && one.dataset.live === 'true');
  const live = liveRows();
  check('QCON a live turn carries its rewind, hidden', live.length >= 1 &&
    live.every((one) => one.hidden === true),
    String(live.length) + ' live / ' + page.rows('.row-rewind').length + ' rewind / ' +
      page.rows('.assistant').length + ' assistant / ' + page.rows('.turn-row').length + ' turnrows');
  page.push({ type: 'finished', session: 'live-1', stop_reason: 'done' });
  await flush(160);
  const after = liveRows();
  check('QCON the run ending brings the rewind back',
    after.length >= 1 && after.every((one) => one.hidden === false),
    after.map((one) => String(one.hidden)).join(','));
}

// The unified pane: one entry, the run tab alive, the object card in
// the pane, the grip owning the width, and the web tab rendering live
// or naming the refusal with its two doors.
async function thePaneIsOneSurfaceWithTheOwnersHandOnIt() {
  const doc = {
    sessions: {
      type: 'sessions', read_at: 'now', current: '',
      counts: { needs: 0, working: 0, background: 0, earlier: 1, total: 1 },
      sessions: [row('pane-1', 'completed', { title: 'a conversation' })],
    },
    state: (asked) => ({ ...emptyState(asked), session: asked }),
    memory: { type: 'memory', hits: [], facts: [{
      id: 'fact-1', name: 'the fact the owner presses',
      description: 'what the corpus knows', fact_type: 'fact', basis: 'the evidence',
      tier: 'fact', recall_count: 1, retired: false,
    }] },
    webFrame: { type: 'web-frame', url: 'https://example.com/x',
      framable: false, reason: "the site's own x-frame-options says DENY",
      content_type: 'text/html' },
  };
  const page = boot({ width: 1440, hash: '#/sessions/pane-1', documents: doc });
  await flush();
  page.open();
  await flush(60);

  // The run tab: the pane opens on it, and the process card paints in it.
  page.rows('#pane-open')[0].click();
  await flush(40);
  check('P the pane opens on the act tab',
    page.body.dataset.pane === 'open' &&
      page.IDS['pane-run'].hidden === false &&
      page.IDS['tab-act'].getAttribute('aria-selected') === 'true',
    page.body.dataset.pane + ' / ' + page.IDS['pane-run'].hidden);
  check('P the process card lives in the pane and painted',
    HTML.indexOf('id="pane-run"') < HTML.indexOf('id="process-card"') &&
      HTML.indexOf('id="process-card"') < HTML.indexOf('id="pane-files"') &&
      page.text('process-state') !== '',
    page.text('process-state'));

  // The object: a press opens the pane with the object card above the
  // body, and the run's own cards stand down while it speaks.
  page.rows('.surfaces-link').find((l) => l.dataset.address === 'memory').click();
  await flush(40);
  const projectRow = page.rows('.section-rail-row')
    .find((row) => row.textContent.includes('everything else'));
  if (projectRow) projectRow.click();
  await flush(40);
  const objectRow = page.rows('.cfg-item')[0];
  if (objectRow) objectRow.click();
  await flush(40);
  // The drawer IS the pane's main component (the owner's 2026-11-18
  // ruling): an object opens the pane ON its detail tab, showing while the
  // run's own view stands down — not stacked above it as a second card.
  check('P the object opens the pane on its document',
    page.body.dataset.pane === 'open' &&
      page.IDS['pane-detail'].hidden === false &&
      page.IDS['tab-read'].getAttribute('aria-selected') === 'true' &&
      page.IDS['read-mode-document'].classList.contains('on') &&
      page.IDS['pane-run'].hidden === true &&
      page.text('dock-object-title').length > 0,
    'pane=' + page.body.dataset.pane +
      ' detail=' + page.IDS['pane-detail'].hidden +
      ' selected=' + page.IDS['tab-read'].getAttribute('aria-selected') +
      ' title=' + page.text('dock-object-title'));
  page.fireOn('dock-object-close', 'click');
  await flush(20);
  // Closing an object retires the detail TAB (the drawer is a pane tab now,
  // not a card stacked above them): the panel hides with it and the pane
  // falls back to the run.
  check('P closing the object returns the act tab',
    page.IDS['pane-detail'].hidden === true &&
      page.IDS['tab-act'].getAttribute('aria-selected') === 'true',
    'detail hidden=' + page.IDS['pane-detail'].hidden +
      ' act=' + page.IDS['tab-act'].getAttribute('aria-selected'));

  // The grip: drag left widens to the cap, the choice persists, the
  // double-click resets, and the separator takes the keyboard. The cap is
  // no longer the whole window (KI-555): at 1440 with the connections
  // column open the pane stops at the column's edge, so the widest it may
  // be is 1440 - stage floor 560 - tissue 320 = 560. Before the fix this
  // case pinned 720, which is exactly the pane painting over 200px of a
  // 320px column — the defect recorded as an expectation.
  const grip = page.rows('#pane-grip')[0];
  grip.fire('pointerdown', { clientX: 1000, pointerId: 1 });
  grip.fire('pointermove', { clientX: 700, pointerId: 1 });
  grip.fire('pointerup', { clientX: 700, pointerId: 1 });
  const widened = page.sandbox.document.documentElement.style.getPropertyValue('--pane-width');
  check('P the drag widens the pane to its cap and persists',
    widened === '560px' &&
      JSON.stringify(page.sandbox.localStorage.getItem('fleet-pane-width')) === '"560"',
    String(widened));
  grip.fire('dblclick', {});
  const reset = page.sandbox.document.documentElement.style.getPropertyValue('--pane-width');
  check('P the double-click resets the width', reset === '440px', String(reset));
  grip.fire('keydown', { key: 'ArrowLeft' });
  const stepped = page.sandbox.document.documentElement.style.getPropertyValue('--pane-width');
  check('P the arrow keys step the width', stepped === '464px', String(stepped));
  check('P the grip is a separator with its bounds declared',
    HTML.includes('role="separator"') && HTML.includes('aria-valuemin="300"') &&
      ruleBlock('.pane-grip').includes('cursor: col-resize'),
    'grip');

  // The web tab: a refusing address names the site's own words and
  // offers the reader door; a framable address renders live in the
  // sandboxed frame; back walks the tab's own history.
  page.IDS['tab-read'].click();
  page.IDS['read-mode-web'].click();
  await flush(20);
  page.IDS['pane-address-box'].value = 'example.com/x';
  page.fireOn('pane-address', 'submit', {});
  await flush(40);
  check('P the refusal names the site and keeps it honest',
    page.text('pane-page').includes('x-frame-options says DENY'),
    page.text('pane-page').slice(0, 120));
  check('P the frame URL carried the normalized address',
    page.calls.some((c) => c.url.includes('/api/web/frame?url=https%3A%2F%2Fexample.com%2Fx')),
    JSON.stringify(page.calls.filter((c) => c.url.includes('/api/web/frame')).map((c) => c.url)));
  page.documents = page.documents || {};
  const reader = page.rows('.pane-web-doors .row-rewind')[0];
  if (reader) reader.click();
  await flush(40);
  check('P the reader door reads the prose',
    page.calls.some((c) => c.url.includes('/api/web?url=')),
    'reader');

  const page2 = boot({
    width: 1440, hash: '#/sessions/pane-1',
    documents: { ...doc, webFrame: { type: 'web-frame', url: 'https://a.example/',
      framable: true, reason: '', content_type: 'text/html' } },
  });
  await flush();
  page2.open();
  await flush(40);
  page2.IDS['tab-read'].click();
  page2.IDS['read-mode-web'].click();
  await flush(20);
  page2.IDS['pane-address-box'].value = 'a.example';
  page2.fireOn('pane-address', 'submit', {});
  await flush(40);
  const frame = page2.rows('.pane-frame')[0];
  check('P a framable address renders live in the sandboxed frame',
    frame && frame.getAttribute('sandbox').includes('allow-scripts') &&
      frame.getAttribute('sandbox').includes('allow-forms') &&
      !frame.getAttribute('sandbox').includes('allow-top-navigation'),
    frame ? frame.getAttribute('sandbox') : 'no frame');
  check('P the out door offers the owner\u2019s browser',
    page2.IDS['pane-web-out'].hidden === false, 'out');
}


// The preview renders the common formats: the zero-dependency ones
// (csv/tsv tables, json trees, images and svg as inert img) end to end
// through the face's own open flow, the markdown table renders while a
// script in a markdown file stays text, and a binary document the fake
// DOM cannot inflate fails gracefully with the pane's own words.
async function thePreviewRendersTheCommonFormats() {
  const page = boot({
    width: 1440, hash: '#/sessions/pane-1',
    documents: {
      sessions: {
        type: 'sessions', read_at: 'now', current: '',
        counts: { needs: 0, working: 0, background: 0, earlier: 1, total: 1 },
        sessions: [row('pane-1', 'completed', { title: 'a conversation' })],
      },
      state: (asked) => ({ ...emptyState(asked), session: asked }),
      tree: { type: 'tree', refused: [], entries: [
        { name: 'data.csv', kind: 'file' },
        { name: 'notes.md', kind: 'file' },
        { name: 'doc.json', kind: 'file' },
        { name: 'logo.png', kind: 'file' },
        { name: 'sheet.xlsx', kind: 'file' },
      ] },
      files: {
        'data.csv': { type: 'file', path: 'data.csv', name: 'data.csv',
          language: 'csv', text: 'name,size\na,1\n"b,x",2' },
        'notes.md': { type: 'file', path: 'notes.md', name: 'notes.md',
          language: 'markdown',
          text: '| a | b |\n|---|---|\n| 1 | 2 |\n\n<script>alert(1)</script>' },
        'doc.json': { type: 'file', path: 'doc.json', name: 'doc.json',
          language: 'json', text: '{"k": [1, 2]}' },
        'logo.png': { type: 'file', path: 'logo.png', name: 'logo.png', language: 'png' },
        'sheet.xlsx': { type: 'file', path: 'sheet.xlsx', name: 'sheet.xlsx', language: 'xlsx' },
      },
    },
  });
  await flush();
  page.open();
  await flush(40);
  page.rows('#pane-open')[0].click();
  await flush(20);
  page.IDS['tab-read'].click();
  page.IDS['read-mode-code'].click();
  await flush(20);
  const open = async (name) => {
    const row = page.rows('.pane-row').find((one) => one.textContent.includes(name));
    if (!row) throw new Error(name + ' has no tree row');
    row.click();
    await flush(40);
    page.IDS['read-mode-preview'].click();
    await flush(40);
  };

  await open('data.csv');
  const cells = page.rows('.pane-data .md-td');
  check('PV the csv renders as a table with the quoted comma as one cell',
    cells.length === 4 &&
      page.rows('.pane-data .md-td').some((td) => td.textContent === 'b,x'),
    String(cells.length));

  await open('notes.md');
  // R6: the preview is marked's render now. The stub's innerHTML does not
  // parse children, so the render is judged from the sanitised HTML the
  // engine produced — semantic tags, not the old md-* classes.
  const renderedMd = String(page.window.__sanitized || '');
  check('PV the markdown table renders',
    /<table>/.test(renderedMd) && /<td>1<\/td>/.test(renderedMd) &&
      /<td>2<\/td>/.test(renderedMd),
    renderedMd.slice(0, 120));
  check('PV the preview hands the document\u2019s HTML to the sanitiser',
    /<script>alert\(1\)/.test(String(page.window.__sanitized || '')),
    String(page.window.__sanitized || '').slice(-60));
  // The R6 contract: no sanitiser, no rendered markdown — the source is
  // shown instead of trusting the parser's output.
  delete page.window.DOMPurify;
  await open('notes.md');
  check('PV no sanitiser, no rendered markdown',
    page.text('pane-preview-body').includes('markdown engine is not loaded'),
    page.text('pane-preview-body').slice(-80));

  await open('doc.json');
  check('PV the json renders as a tree',
    page.rows('.pane-json-node').length >= 1 &&
      page.rows('.pane-json-leaf').length === 2,
    String(page.rows('.pane-json-leaf').length));

  await open('logo.png');
  const img = page.rows('.pane-image')[0];
  check('PV an image renders from the contained route',
    img && String(img.src).includes('/api/preview?path=logo.png'),
    String(img && img.src));

  await open('sheet.xlsx');
  check('PV a binary document fails gracefully in the pane\u2019s own words',
    page.text('pane-preview-body').includes('would not render'),
    page.text('pane-preview-body').slice(0, 80));
  // The render pins now live in their own cases (theSheetRendersItsOwnForm
  // and theDeckFallsBackToTheOutlineByName feed the committed fixtures
  // through the face's own reader); what stays here is the vendor record
  // those cases rely on.
  const VENDOR_JSON = fs.readFileSync(
    path.join(ROOT, 'src/gui/assets/vendor/VENDOR.json'), 'utf8');
  check('PPTXF the viewer is vendored with its version, licence and route',
    VENDOR_JSON.includes('PPTXjs') && VENDOR_JSON.includes('2.0.0') &&
      VENDOR_JSON.includes('MIT') &&
      RUST.includes('/vendor/pptxjs.umd.js') &&
      fs.existsSync(path.join(ROOT, 'src/gui/assets/vendor/pptxjs.LICENSE')),
    'pptx vendor');

  // The Rust side's fences, read from the source: the credential
  // refusal, the allowlist-derived type, nosniff, attachment.
  check('PV the preview route\u2019s fences are in the served page\u2019s backend',
    RUST.includes('a credential file is never served') &&
      RUST.includes('X-Content-Type-Options: nosniff') &&
      RUST.includes('Content-Disposition: attachment') &&
      RUST.includes('preview_content_type'),
    'source');
}


// The onboarding's document shape, shared by the cases below.
function onboardDoc(options) {
  const opts = options || {};
  const door = {
    eyebrow: 'fleet \u00b7 first run',
    title: 'One account, and fleet can think.',
    lede: 'Fleet answers in this window, reads and writes files in a folder you choose, ' +
      'and remembers what you decide. It needs one AI account, and nothing else.',
    discovered: !!opts.discovered,
    discovered_label: opts.discovered ? 'Use the account already on this machine' : '',
    field_label: 'paste the account\u2019s key',
    action: 'Use it',
    mechanism: 'Fleet picks a model per task among the accounts it can reach.',
  };
  const steps = [
    { id: 'home', done: true, skipped: false, evidence: 'the home is in place' },
    { id: 'first-llm', done: !opts.door, skipped: false, evidence: '' },
    { id: 'judgment', done: false, skipped: false, evidence: '', proof: 'no system-one key yet' },
    { id: 'lanes', done: false, skipped: false, evidence: '' },
    { id: 'projects', done: false, skipped: false, evidence: '' },
    { id: 'github', done: false, skipped: false, evidence: '' },
    { id: 'roster', done: false, skipped: false, evidence: '' },
  ].map((step) => ({
    ...step,
    proof: step.proof || ('proof for ' + step.id + ': 0 of 1 read'),
    narration: {
      eyebrow: 'fleet \u00b7 ' + step.id,
      title: step.id === 'judgment' ? 'At minimum one system-one model.'
        : step.id === 'lanes' ? 'Small specialists, called when they help.'
          : step.id === 'projects' ? 'Point fleet at your work.'
            : step.id === 'github' ? 'Check claims against the record.'
              : step.id === 'roster' ? 'Which model does what.' : 'Fleet can think already.',
      lede: 'One sentence of benefit for ' + step.id + '.',
      action: 'Set it up',
      skip: (step.id === 'first-llm' || step.id === 'judgment')
        ? '' : 'Without it, fleet still works, with a named cost.',
      mechanism: 'The mechanism words live here: KEY_NAME, endpoint, roster, tier, vault, port.',
    },
  }));
  return {
    type: 'onboard',
    preview: {
      chain: [
        { provider: 'stepfun', model: 'step-5-preview', state: 'ready', billing: 'plan' },
        { provider: 'deepseek', model: 'deepseek-flash', state: 'no key', billing: 'payg' },
      ],
      quick: 'stepfun/step-5-preview',
      hard: 'stepfun/step-5-preview',
      tail: 'deepseek',
      ceilings: [
        { what: "the judge's asks", in_force: 0.05, compiled: 0.05, tightened: false },
      ],
      windows: { declared: 12, floor: 100000 },
    },
    ready: !opts.door,
    first_incomplete: opts.door ? 'first-llm' : 'lanes',
    steps,
    door,
    completion: { doctor: false, routed_turn: false, recalled_fact: false, tower_project: false, green: false },
  };
}

// The door: one screen, one decision, benefit before mechanism — inside
// the welcome's own frame and its own typography, with the mechanism
// words kept to the disclosure. And the cards: the capabilities the
// machine can still gain, each with a real "not now".
async function theDoorIsTheWelcomeInItsFirstRunState() {
  const page = boot({
    width: 1440, hash: '#/chat',
    documents: { onboard: onboardDoc({ door: true }), state: (asked) => emptyState(asked) },
  });
  await flush();
  page.open();
  await flush(80);

  // The door lives inside .empty, beside the landing's one question
  // (U49): the eyebrow and lede are retired — the title carries it.
  check('OB the door is the welcome\u2019s own frame',
    HTML.indexOf('id="onboard-door"') > HTML.indexOf('id="empty-title"') &&
      HTML.indexOf('id="onboard-door"') < HTML.indexOf('id="onboard-cards"'),
    'markup order');
  check('OB the door\u2019s title is the welcome\u2019s own, overridden',
    page.text('empty-title') === 'One account, and fleet can think.',
    page.text('empty-title'));
  check('OB the landing asks and carries only the way back',
    HTML.includes('What do you want to work on?') &&
      HTML.includes('id="recent"') &&
      !HTML.includes('id="empty-eyebrow"') && !HTML.includes('id="empty-lede"') &&
      !HTML.includes('id="home-stats"') && !HTML.includes('id="greet"') &&
      !HTML.includes('id="offers"'),
    'the retired surfaces stay gone; the way back is the one addition');

  // The default path carries no mechanism word; each lives in the
  // disclosure only.
  const shown = [page.text('empty-title'), page.text('onboard-key-go')].join(' ');
  const banned = ['_API_KEY', 'KEY_NAME', 'endpoint', 'roster', 'tier', 'vault', 'port'];
  check('OB the door\u2019s default path names no mechanism',
    banned.every((word) => shown.indexOf(word) === -1),
    shown);
  check('OB the mechanism has its own disclosure',
    page.text('onboard-mechanism-body').indexOf('Fleet picks a model') !== -1,
    page.text('onboard-mechanism-body'));

  // One decision per screen: the run composer stands down for the door's
  // own field, which is the composer's shape.
  check('OB one field on screen while the door is up',
    page.IDS.composer.hidden === true && page.IDS['onboard-door'].hidden === false,
    'composer hidden: ' + page.IDS.composer.hidden);

  // The ladder is the document's own: one line per step it declares, each with
  // its mark, and exactly one saying "now". A door that always showed three
  // would be telling the owner a story the document does not — and the count
  // is the fixture's, so the case cannot drift from it silently.
  const ladder = page.rows('.onboard-ladder-step');
  const marks = page.rows('.onboard-ladder-mark').map((one) => String(one.textContent));
  check('OB the ladder carries one line per step the document declares',
    ladder.length === 7, 'ladder=' + ladder.length);
  check('OB every ladder step is marked and exactly one says now',
    marks.length === ladder.length && marks.filter((m) => m === 'now').length === 1,
    marks.join(','));

  // No metric bar on a first-run home: the landing's own furniture is the
  // title, the ladder and the decision. The counts belong to the work home.
  const landing = page.IDS.empty;
  check('OB a first-run landing carries no metric bar',
    landing.dataset.onboard === 'door' &&
      page.rows('.counts').filter((one) => one.parentNode === landing).length === 0,
    'token=' + landing.dataset.onboard);
  check('OB the door\u2019s field is the composer\u2019s own shape',
    HTML.includes('class="composer onboard-key"') &&
      HTML.includes('class="foot-btn send"') &&
      CSS.includes('.onboard-key'),
    'markup');

  // No new design chrome: every colour/radius/font token the onboarding
  // CSS names is one the console already declares.
  const onboardCss = CSS.slice(CSS.indexOf('.onboard-door'), CSS.indexOf('.onboard-cards'));
  const tokens = Array.from(onboardCss.matchAll(/var\((--[a-z0-9-]+)/g)).map((m) => m[1]);
  const undeclared = Array.from(new Set(tokens)).filter((token) => !CSS.includes(token + ':'));
  check('OB the onboarding introduces no new token',
    undeclared.length === 0,
    undeclared.join(', '));
  const literalColours = Array.from(onboardCss.matchAll(/#[0-9a-f]{3,8}\b|rgb\(/gi));
  check('OB the onboarding names no literal colour', literalColours.length === 0,
    String(literalColours.length));
  // And no font outside the declared set.
  check('OB the onboarding names no new font',
    !/font-family:/.test(onboardCss),
    'font-family appears');
}

// The cards: only what can still be gained, one action and one real
// "not now", and the stack disappears when nothing is left.
async function theCapabilityCardsAreOnDemand() {
  const page = boot({
    width: 1440, hash: '#/chat',
    documents: { onboard: onboardDoc({ door: false }), state: (asked) => emptyState(asked) },
  });
  await flush();
  page.open();
  await flush(80);

  check('OB the door is down once fleet can answer',
    page.IDS['onboard-door'].hidden === true && page.IDS.composer.hidden === false,
    'door hidden: ' + page.IDS['onboard-door'].hidden);
  const cards = page.rows('.onboard-card');
  check('OB the cards are the capabilities still missing',
    cards.length === 5, String(cards.length));
  // U41: the judgment step is REQUIRED — it carries the action and no
  // "not now"; every optional card keeps its real one.
  const judgment = cards.filter((one) => one.textContent.includes('system-one'))[0];
  check('OB the judgment card is required — action, no not-now',
    !!judgment && judgment.querySelectorAll('.foot-btn').length >= 1 &&
      judgment.querySelectorAll('.row-rewind').length === 0,
    'not-now=' + (judgment ? judgment.querySelectorAll('.row-rewind').length : 'no card'));
  check('OB every optional card carries one action and a real not-now',
    cards.filter((card) => card !== judgment).every((card) =>
      card.querySelectorAll('.foot-btn').length === 1 &&
      card.querySelectorAll('.row-rewind').length === 1),
    String(cards.length));
  check('OB every card carries a visible proof',
    cards.every((card) => card.querySelectorAll('.onboard-proof').length === 1) &&
      page.text('onboard-cards').includes('proof for'),
    String(cards.length) + ' cards');
  check('OB a card names its benefit before its mechanism',
    cards[0].textContent.indexOf('One sentence of benefit') <
      cards[0].textContent.indexOf('The mechanism words live here'),
    cards[0].textContent.slice(0, 120));

  // The stack shrinks to nothing when every card is settled.
  const done = onboardDoc({ door: false });
  done.steps = done.steps.map((step) => ({ ...step, done: true }));
  const quiet = boot({
    width: 1440, hash: '#/chat',
    documents: { onboard: done, state: (asked) => emptyState(asked) },
  });
  await flush();
  quiet.open();
  await flush(80);
  check('OB a settled fleet shows no setup at all',
    quiet.rows('.onboard-card').length === 0 && quiet.IDS['onboard-cards'].hidden === true,
    String(quiet.rows('.onboard-card').length));
}


// The strategy step ends in a confirmation to read, not a green to earn:
// the chain as built, what a quick task and a hard one do, the ceilings
// in force, and the window fallback — then one confirmation.
async function theStrategyStepShowsItsPreview() {
  const posts = [];
  const page = boot({
    width: 1440, hash: '#/chat',
    documents: { onboard: onboardDoc({ door: false }), state: (asked) => emptyState(asked) },
  });
  await flush();
  page.open();
  await flush(80);

  const rosterCard = page.rows('.onboard-card').find((card) =>
    card.textContent.includes('Which model does what'));
  check('PV the strategy card is on the stack', !!rosterCard,
    String(page.rows('.onboard-card').length));
  // Its own action opens the preview, not the settings surface.
  rosterCard.querySelector('.foot-btn').click();
  await flush(60);
  const preview = page.rows('.onboard-preview')[0];
  check('PV the strategy step opens its preview in place', !!preview,
    String(page.rows('.onboard-preview').length));
  check('PV the preview shows the chain as built',
    page.rows('.onboard-chain-row').length === 2 &&
      page.text('onboard-cards').includes('stepfun') &&
      page.text('onboard-cards').includes('deepseek'),
    String(page.rows('.onboard-chain-row').length));
  check('PV the chain names the last resort',
    page.text('onboard-cards').includes('last resort') &&
      page.text('onboard-cards').includes('serves only after every other'),
    'tail');
  check('PV the preview names what a quick task and a hard one do',
    page.rows('.onboard-workload').length === 2 &&
      page.text('onboard-cards').includes('a quick task') &&
      page.text('onboard-cards').includes('a hard one') &&
      page.text('onboard-cards').includes('stepfun/step-5-preview'),
    'workloads');
  check('PV the preview names the ceilings in force',
    page.rows('.onboard-cap').length === 1 &&
      page.text('onboard-cards').includes('$0.05') &&
      page.text('onboard-cards').includes('a day'),
    page.text('onboard-cards').includes('$0.05') ? 'caps' : 'missing');
  check('PV the preview names the window fallback',
    page.text('onboard-cards').includes('12 models carry a declared context window') &&
      page.text('onboard-cards').includes('100000 tokens'),
    'windows');
  // The confirmation posts the decision and records it.
  const confirm = page.rows('.onboard-acts .foot-btn')[0];
  check('PV the preview ends in a confirmation and a real not-now',
    !!confirm && page.rows('.onboard-acts .row-rewind').length === 2,
    String(page.rows('.onboard-acts .row-rewind').length));
  confirm.click();
  await flush(60);
  const confirmed = page.calls.filter((call) =>
    call.url.startsWith('/api/onboard') && String(call.body).includes('"op":"confirm"'));
  check('PV confirming posts the decision', confirmed.length === 1,
    JSON.stringify(page.calls.filter((c) => c.url.startsWith('/api/onboard')).map((c) => c.body)));
  void posts;
}


  // The relay transport: a face reached through a relay stores the
