  // The huddles surface's own states (the huddles-ux plan's C9): the
  // invitation when the home keeps no rooms, the reason when the read was
  // refused — and never a room that is not there.
  async function theHuddleSurfaceNamesItsStates() {
    const empty = boot({
      documents: {
        huddles: { type: 'huddles', active: [], inactive: [], ended: [],
          counts: { active: 0, inactive: 0, ended: 0 } },
        settings: {
          roles: {
            dir: '/tmp',
            entries: [
              { name: 'designer', description: 'makes pages', tools: [], skills: [],
                shapes: [], overlay: 'voice' },
              { name: 'scholar', description: 'grounds every claim', tools: [], skills: [],
                shapes: [], overlay: 'voice' }
            ]
          }
        }
      }
    });
    await flush();
    empty.open();
    await flush();
    empty.hash('#/huddles');
    for (let i = 0; i < 8; i++) await flush();
    // The invitation names the thing the owner actually starts — a
    // huddle — and says what one is without a single internal word
    // (the owner's 2026-11-18 copy ruling).
    const emptyCopy = String(empty.IDS['room-empty'].textContent);
    check('C9 no rooms yet reads as the invitation',
      emptyCopy.indexOf('Start a huddle') !== -1,
      emptyCopy.slice(0, 80));
    check('C9 the invitation explains a huddle in plain words',
      emptyCopy.indexOf('working session') !== -1 &&
        !/\bface\b|\bseat\b|\blane\b|\bledger\b/.test(emptyCopy),
      emptyCopy.slice(0, 160));
    const picks = empty.rows('.picks .pick');
    check('C9 the invitation offers the home’s bots',
      picks.length >= 1, 'picks=' + picks.length);
    check('C9 the welcome never stands beside it',
      empty.IDS['empty'].hidden === true, 'welcome');

    const refused = boot({
      documents: { huddles: { type: 'huddles', refused: ['the archive could not be read: locked'] } }
    });
    await flush();
    refused.open();
    await flush();
    refused.hash('#/huddles');
    for (let i = 0; i < 8; i++) await flush();
    check('C9 a refused read names its reason',
      String(refused.IDS['room-empty'].textContent).indexOf('could not be read') !== -1,
      String(refused.IDS['room-empty'].textContent).slice(0, 90));
  }


  // The band the owner reported (2026-11-18): "on the top of the chat area
  // there is a band that sometimes displays text from other pages, for
  // instance if you go to the huddle page the text from that page shows
  // even if you are in the conversations page."
  //
  // The cause was one line in paintRoomHead: it UN-hid the invitation
  // whenever the loaded session was not a room, on every paint and on
  // every surface. So any state read while a conversation was open put the
  // huddles column's copy at the top of the column — and the state read
  // runs on every event, which is why it "sometimes" showed.
  //
  // The rule this pins: each element of the column's top has exactly one
  // owner, and the owner guards its own surface.
  async function theColumnsHeadsNeverBorrowAnotherSurfacesText() {
    const conv = {
      type: 'sessions', read_at: 'now', current: 'c1',
      counts: { needs: 0, working: 0, background: 0, earlier: 1, total: 1 },
      sessions: [row('c1', 'completed', { title: 'a conversation of mine' })],
    };
    const page = boot({
      documents: {
        sessions: conv,
        huddles: { type: 'huddles', active: [], inactive: [], ended: [],
          counts: { active: 0, inactive: 0, ended: 0 } },
        state: (asked) => ({ ...emptyState(asked), session: asked, members: [] }),
      },
    });
    await flush();
    page.open();
    await flush();

    // 1. A plain conversation: the huddles copy must not be on the page.
    page.hash('#/sessions/c1');
    for (let i = 0; i < 8; i++) await flush();
    check('BAND a conversation shows no huddles invitation',
      page.IDS['room-empty'].hidden === true,
      String(page.IDS['room-empty'].textContent).slice(0, 80));
    check('BAND a conversation shows no room head',
      page.IDS['room-head'].hidden === true, '');
    check('BAND a conversation does show its own head',
      page.IDS['conv-head'].hidden === false, '');

    // 2. Visit huddles, then come back: the walk that produced the report.
    page.hash('#/huddles');
    for (let i = 0; i < 8; i++) await flush();
    check('BAND huddles does show its invitation',
      page.IDS['room-empty'].hidden === false, '');
    page.hash('#/sessions/c1');
    for (let i = 0; i < 8; i++) await flush();
    check('BAND leaving huddles takes its text with it',
      page.IDS['room-empty'].hidden === true,
      'the invitation followed the owner to the conversation');
    check('BAND leaving huddles takes its head with it',
      page.IDS['room-head'].hidden === true, '');

    // 3. A state read is not a surface: it must not put the band back.
    //    This is the path that made the report intermittent.
    page.push({ type: 'token', session: 'c1', text: 'hello again' });
    for (let i = 0; i < 10; i++) await flush();
    check('BAND a repaint does not resurrect the invitation',
      page.IDS['room-empty'].hidden === true,
      'a state read un-hid the invitation while a conversation was open');
  }

  // The bots rail's personas (the icons plan's C6): a persona is a mark —
  // the same initial disc a huddle draws — and the channels row keeps the
  // robot, so the two kinds never look alike.
  async function theBotsRailWearsItsInitials() {
    const page = boot({
      documents: {
        channels: {
          type: 'channels',
          conversations: {
            type: 'conversations', bound: 20, needs: 0, count: 0,
            personas: [{ name: 'designer', sessions: [], needs: 0, turned_back: 0 }]
          },
          service: { channels: [] }, channels: [], activity: [], devices: []
        }
      }
    });
    await flush();
    page.open();
    await flush();
    page.hash('#/bots');
    for (let i = 0; i < 8; i++) await flush();
    const rows = page.rows('#bots-rail .section-rail-row');
    const discs = page.rows('#bots-rail .section-rail-mark .pmark');
    check('ICONS a persona row wears its initial disc',
      discs.length === 1 && String(discs[0].textContent) === 'd',
      'discs=' + discs.length + ' text=' + (discs[0] ? String(discs[0].textContent) : '-'));
    check('ICONS the channels row keeps the robot, not a disc',
      rows.length === 4 && discs.length === 1, 'rows=' + rows.length);
    // The kanzo board's row wears the robot too: it is a way work arrives
    // from outside a conversation, like the channels, and not a persona.
    const kanzoRow = rows.filter((one) => one.dataset.section === 'kanzo')[0];
    check('ICONS the kanzo row keeps the robot, not a disc',
      !!kanzoRow && String(kanzoRow.textContent).includes('kanzo board'),
      kanzoRow ? String(kanzoRow.textContent) : 'none');
    // The morning read (P5's AC) leads the rail with the robot too — the
    // two mark kinds stay apart there as well.
    const morning = rows[0];
    check('ICONS the morning read leads the rail without a disc',
      !!morning && morning.dataset.section === 'morning-read' &&
        !String(morning.textContent).includes('channels'),
      morning ? morning.dataset.section : 'none');
    // P0 of the face rethink: the disc's colour is the presence table's, not
    // a second map's. `designer` is lane 4 — and an unknown persona still
    // gets the accent and its own letter rather than an empty disc.
    const tint = discs[0] && discs[0].style
      ? discs[0].style.getPropertyValue('--tint') : '';
    check('P0 a persona disc takes its tint from the presence table',
      tint === 'var(--lane-4)', 'tint=' + (tint || '(none)'));
  }

