  // sys1's verdict rides the seat as data (the huddles plan's C10): the
  // reason before the buttons, and which judgment produced it — a seat
  // with no verdict shows no line rather than implying one.
  async function theSeatCarriesSys1sVerdict() {
    const page = boot({
      documents: {
        state: (asked) => ({ ...emptyState(asked), session: asked }),
        reply: { type: 'seat', tool: 'write_file', summary: 'rewrite docs/x.md',
          verdict: { destructive: true,
            reason: 'an overwrite discards what is there',
            confidence: 0.91, judged_from: 'sys1' } }
      }
    });
    await flush();
    page.open();
    await flush();
    // A seat arrives through the stream's `seat` event.
    page.push({ type: 'seat', tool: 'write_file', summary: 'rewrite docs/x.md',
      label: 'write_file', allowlistable: false,
      verdict: { destructive: true,
        reason: 'an overwrite discards what is there',
        confidence: 0.91, judged_from: 'sys1' } });
    await flush(40);
    const verdict = page.IDS['seat-verdict'];
    check('C10 the seat carries the judged reason',
      !verdict.hidden &&
        String(verdict.textContent).indexOf('an overwrite discards what is there') !== -1,
      verdict.hidden ? 'hidden' : String(verdict.textContent));
    check('C10 the seat names which judgment produced it',
      String(verdict.textContent).indexOf('sys1') !== -1,
      String(verdict.textContent));

    const plain = boot({
      documents: { state: (asked) => ({ ...emptyState(asked), session: asked }) }
    });
    await flush();
    plain.open();
    await flush();
    plain.push({ type: 'seat', tool: 'bash', summary: 'run cargo test',
      label: 'bash', allowlistable: true });
    await flush(40);
    check('C10 a seat with no verdict shows no line',
      plain.IDS['seat-verdict'].hidden,
      String(plain.IDS['seat-verdict'].hidden));
  }

  // A capability gap is a hiring decision, not a blocker (the huddles
  // plan's C5): a name the home cannot convene — a tool, a skill, or an
  // unnamed capability — offers to author a persona for it, and that persona
  // persists in the home for every later huddle.
  // A capability gap is a hiring decision (the huddles plan's C5): a name
  // the home cannot convene offers to author a persona for it, and that door
  // searches the catalog FIRST — a role that already covers the gap is brought
  // up with a convene press rather than re-authored.
  async function aGapOffersToHireAPersona() {
    const bootPage = (gapName) => boot({
      hash: '#/settings',
      reply: { type: 'join', persona: 'scholar' },
      documents: {
        settings: {
          type: 'settings', read_at: 'now',
          scalars: [], lists: [], rules: [], env: [], cron: [],
          soul: { present: false, text: '' },
          router: { pin: '', judged: ['quick'],
            tiers: [{ workload: 'quick', candidates: ['a/one'], resolved: 'a/one', reverts: false }],
            min_confidence: 0.5, default_workload: 'quick', allow_api_models: false, roster: [] },
          catalog: {
            models: [], providers: [],
            tools: ['read_file', 'list_dir', 'search'],
            skills: ['a11y-scan', 'grounded-citations']
          },
          lanes: { document: {}, lanes: [], refused: [] },
          servers: { servers: [], refused: [] },
          tools: { calls_per_turn: 0, definition_tokens: 0, disabled: [], last_sweep: '', window: 0 },
          vault: { names: [], exists: true, passphrase: false, plaintext: [] },
          roles: { dir: '/tmp', entries: [
            { name: 'scholar', description: 'grounds every claim',
              tools: [], skills: [], shapes: [], overlay: 'voice' }
          ] }
        },
        state: (asked) => ({
          ...emptyState(asked), session: asked,
          members: [{ name: 'scholar', voice: 'grounds every claim' }],
          events: [
            { type: 'message', role: 'owner', text: 'the launch brief' },
            { type: 'recommend', name: gapName, kind: 'skill',
              reason: 'the contrast pairs need an accessibility pass', from: 'scholar' }
          ]
        })
      }
    });
    // A gap the catalog already covers: the door offers the convene, not a
    // blank authoring form.
    const covered = bootPage('scholar');
    await flush();
    covered.open();
    await flush();
    covered.hash('#/chat');
    await flush(40);
    let card = covered.rows('.suggest')[0];
    let hire = card ? card.find((one) => one.className === 'press primary')[0] : null;
    check('C5 a gap the catalog covers still opens the door',
      !!hire && String(hire.textContent).indexOf('create a persona') !== -1,
      hire ? String(hire.textContent) : 'no press');
    if (hire) hire.click();
    await flush(20);
    check('C5 the door opens', !covered.IDS['persona-door'].hidden, 'hidden');
    const matches = covered.IDS['persona-matches'].find((one) =>
      String(one.className || '').split(/\s+/).includes('persona-match'));
    const press = matches.length
      ? matches[0].find((one) => one.className === 'press')[0]
      : null;
    check('C5 the catalog offers the matching role, not a blank form',
      matches.length === 1 &&
        String(press && press.textContent).indexOf('convene') !== -1,
      matches.length + ':' + (press ? String(press.textContent) : 'none'));
    if (press) press.click();
    await flush(40);
    const joined = covered.calls.filter((c) =>
      c.url.indexOf('/api/session/join') === 0 &&
      String(c.body || '').indexOf('"persona":"scholar"') !== -1);
    check('C5 bringing up a role convenes it', joined.length === 1,
      JSON.stringify(covered.calls.map((c) => c.url)));

    // A genuinely new capability: the door offers authoring, and the
    // engagement is a choice.
    const fresh = bootPage('a11y-scan');
    await flush();
    fresh.open();
    await flush();
    fresh.hash('#/chat');
    await flush(40);
    card = fresh.rows('.suggest')[0];
    hire = card ? card.find((one) => one.className === 'press primary')[0] : null;
    if (hire) hire.click();
    await flush(20);
    check('C5 the door opens for a new capability',
      !fresh.IDS['persona-door'].hidden, 'hidden');
    const none = fresh.IDS['persona-matches'].find((one) =>
      String(one.className || '').split(/\s+/).includes('persona-match'));
    check('C5 a gap with no catalog match offers authoring', none.length === 0,
      String(none.length));
    check('C5 the engagement is a choice',
      !!fresh.IDS['persona-temporal'], 'no select');
    fresh.IDS['persona-name'].value = 'a11y-reviewer';
    fresh.IDS['persona-description'].value = 'audits contrast and focus';
    fresh.IDS['persona-create'].click();
    await flush(40);
    const writes = fresh.calls.filter((c) => c.url === '/api/settings' &&
      String(c.body || '').indexOf('"op":"role"') !== -1);
    check('C5 the persona is written through the role writer',
      writes.length === 1 &&
        String(writes[0].body).indexOf('"name":"a11y-reviewer"') !== -1,
      writes.length ? String(writes[0].body) : 'no write');
    const joins = fresh.calls.filter((c) => c.url.indexOf('/api/session/join') === 0);
    check('C5 the new persona is convened into the room', joins.length === 1,
      JSON.stringify(fresh.calls.map((c) => c.url)));
  }


  // Ending a room is the owner's verb and the rail reflects it: the archive
  // posts the engagement, and the rail's next read moves the room from
  // active to ended — a room put away reads as put away, not as parked.
  async function endingARoomMovesItToTheRail() {
    const room = (state) => ({
      id: 'room-1', title: 'the-q3-board', goal: 'the launch',
      personas: ['scholar'], avatars: {}, awaiting_you: false,
      state: state.archived['room-1'] ? 'archived' : 'working',
      preview: 'the hero copy is tightened', from: 'scholar',
      last_write: 1793807000, current: false, deliverables: 0,
      knowledge: { recalled: 0, wrote: 0 }, parent: null, children: []
    });
    const page = boot({
      hash: '#/huddles/room-1',
      documents: {
        sessions: {
          type: 'sessions', read_at: 'now', current: '',
          counts: { needs: 0, working: 1, background: 0, earlier: 0, total: 1 },
          sessions: [row('room-1', 'working', { title: 'the-q3-board' })]
        },
        state: (asked) => ({
          ...emptyState(asked), session: asked, goal: 'the launch',
          members: [{ name: 'scholar', voice: 'grounds every claim' }]
        }),
        huddles: (state) => ({
          type: 'huddles',
          active: state.archived['room-1'] ? [] : [room(state)],
          inactive: [],
          ended: state.archived['room-1'] ? [room(state)] : [],
          counts: {
            active: state.archived['room-1'] ? 0 : 1,
            inactive: 0,
            ended: state.archived['room-1'] ? 1 : 0
          }
        })
      }
    });
    await flush();
    page.open();
    await flush(40);
    const archive = page.IDS['room-archive'];
    check('ARCH the room carries the archive verb', !!archive, 'none');
    if (!archive) return;
    archive.click();
    await flush(60);
    const posted = page.calls.filter((c) => c.url === '/api/session/archive' &&
      String(c.body || '').indexOf('"archived":true') !== -1);
    check('ARCH the verb posts the engagement', posted.length === 1,
      JSON.stringify(page.calls.map((c) => c.url)));
    page.hash('#/huddles');
    await flush(60);
    const groups = page.rows('.rooms-group span').map((one) => String(one.textContent).trim());
    check('ARCH the column moves the room to ended',
      groups.indexOf('ended') !== -1 && groups.indexOf('active') === -1,
      groups.join(','));
    const fold = page.rows('.rooms-group-fold');
    if (fold.length) fold[0].click();
    await flush(30);
    const endedRows = page.rows('.room-row');
    check('ARCH the ended section holds the room', endedRows.length === 1,
      String(endedRows.length));
  }

