async function theSpineFeedsTheLensesAndThePivotStaysInPlace() {
  const page = boot({
    documents: {
      tissue: { type: 'tissue', nodes: [
        { id: 'install', kind: 'install', label: 'this install', live: true },
        { id: 't1', kind: 'task', label: 'the spine task' },
      ], edges: [], bounded: 60, omitted: 0 },
      workspace: { type: 'workspace', tasks: [
        { id: 't1', title: 'the spine task', status: 'working', assignee: 'owner' },
      ], deliverables: [], threads: [], instances: [],
        intelligence: { tools: 2, workflows: 1 } },
    },
    // The board left the spine when it became an execution view (the
    // owner's 2026-11-18 ruling): it now reads `/api/board`, one card per
    // approved plan. The claim this case makes — ONE read feeds the lens,
    // and the pivot renders in place rather than fetching a foreign panel
    // — is still true of the surfaces the spine feeds, so it is asserted
    // on the inbox, which reads the spine for its work rows.
    hash: '#/inbox',
  });
  page.open();
  await flush(120);
  const spineFetches = page.calls.filter((c) => c.url === '/api/workspace' && c.method === 'GET').length;
  check('S6 one read feeds the lens', spineFetches >= 1,
    'spine fetches=' + spineFetches);
  // The board reads ITS OWN document now, and never the old tasks route.
  const boardPage = boot({
    documents: { board: { type: 'board', read_at: 'now', refused: [], tasks: [],
      counts: { queued: 0, 'in-process': 0, done: 0, plans: 0 }, plans: [] },
      state: (asked) => emptyState(asked), onboard: onboardDoc({ door: false }) },
    hash: '#/board',
  });
  boardPage.open();
  await flush(160);
  check('S6 the board reads its own document',
    boardPage.calls.filter((c) => c.url === '/api/board').length >= 1 &&
      boardPage.calls.filter((c) => c.url === '/api/tasks').length === 0,
    'board=' + boardPage.calls.filter((c) => c.url === '/api/board').length +
      ' tasks=' + boardPage.calls.filter((c) => c.url === '/api/tasks').length);
  page.hash('#/board');
  await flush(120);
  // P0 of the face rethink: every board head renders through `answerHead` —
  // eyebrow, display title, the sentence, and no count inside it. A number in
  // the head is an instrument, and instruments sit beside it, never inside
  // the sentence the owner reads.
  check('P0 the answer head carries eyebrow, title and sentence',
    page.rows('.page-head').length >= 1 &&
      page.rows('.page-head .page-eyebrow').length >= 1 &&
      page.rows('.page-head .page-title').length >= 1 &&
      page.rows('.page-head .page-note').length >= 1,
    page.rows('.page-head').length + ' heads');
  check('P0 the answer head carries no count strip',
    page.rows('.page-head .badge').length === 0 &&
      page.rows('.page-head .surface-strip').length === 0,
    page.rows('.page-head .badge').length + ' badges / ' +
      page.rows('.page-head .surface-strip').length + ' strips');
  // The pivot renders in place: the address reflects the lens, and the
  // workspace spine is re-read to project it — never a foreign panel.
  const nodes = page.IDS['tissue-graph'].querySelectorAll('.tissue-node');
  const taskNode = Array.from(nodes).find((n) => {
    const title = n.querySelector('title');
    return title && title.textContent === 'the spine task';
  });
  check('S6 the graph offers the task node', !!taskNode, 'node present');
  const spineBefore = page.calls.filter((c) => c.url === '/api/workspace').length;
  if (taskNode) taskNode.click();
  await flush(80);
  check('S6 the pivot reflects the lens in the address',
    page.window.location.hash === '#/desk', 'hash=' + page.window.location.hash);
  check('S6 the pivot re-reads the spine to project the lens',
    page.calls.filter((c) => c.url === '/api/workspace').length >= spineBefore + 1,
    'spine reads: ' + page.calls.filter((c) => c.url === '/api/workspace').length);
}

